package com.github.orgonag.fbclan;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

// Not a unit test: the standard RuneLite plugin-template dev launcher,
// wired to `./gradlew run` via build.gradle's mainClass.
public class FinalBossPluginTest
{
    public static void main(String[] args) throws Exception
    {
        ExternalPluginManager.loadBuiltin(FinalBossPlugin.class);
        RuneLite.main(args);
    }
}

package com.github.orgonag.fbclan;

import com.github.orgonag.fbclan.clan.ClanContent;
import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.drops.DropLogger;
import com.github.orgonag.fbclan.drops.DropRates;
import com.github.orgonag.fbclan.drops.DropRules;
import com.github.orgonag.fbclan.lfg.Killcounts;
import com.github.orgonag.fbclan.lfg.LfgCommand;
import com.github.orgonag.fbclan.lfg.PartyApi;
import com.github.orgonag.fbclan.lfg.PartyBoard;
import com.github.orgonag.fbclan.pbs.PersonalBests;
import com.github.orgonag.fbclan.stats.CaBadges;
import com.github.orgonag.fbclan.stats.MemberStats;
import com.github.orgonag.fbclan.ui.AnnouncementsTab;
import com.github.orgonag.fbclan.ui.DropLogTab;
import com.github.orgonag.fbclan.ui.PartiesTab;
import com.github.orgonag.fbclan.ui.Sidebar;
import com.google.inject.Provides;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.http.api.loottracker.LootRecordType;

/**
 * Clan plugin for the Final Boss OSRS clan (wiseoldman.net group 1055).
 *
 * External services: Wise Old Man (one read per login to verify
 * membership), the clan's Supabase database (drop log, LFG parties,
 * screenshots, personal bests, member stats, and the read-only curated
 * content), the OSRS hiscores via RuneLite's client (optional LFG kill
 * counts), and an optional user-supplied Discord webhook. Nothing about
 * the player leaves the client until the WOM check passes; each upload
 * can be switched off individually. See {@link FinalBossConfig}.
 */
@Slf4j
@PluginDescriptor(
    name = "Final Boss",
    description = "Clan tools for Final Boss — announcements, drop log, LFG, and PB leaderboards",
    tags = {"clan", "final boss", "drops", "lfg", "looking for group", "leaderboard", "personal best", "pb", "announcements"}
)
public class FinalBossPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ClientToolbar toolbar;
    @Inject private ScheduledExecutorService executor;
    @Inject private FinalBossConfig config;
    @Inject private Clan clan;
    @Inject private ClanContent content;
    @Inject private DropRates dropRates;
    @Inject private DropLogger drops;
    @Inject private PersonalBests pbs;
    @Inject private MemberStats stats;
    @Inject private CaBadges badges;
    @Inject private PartyBoard parties;
    @Inject private PartyApi partyApi;
    @Inject private Killcounts killcounts;
    @Inject private LfgCommand lfgCommand;
    @Inject private Sidebar sidebar;
    @Inject private AnnouncementsTab announcementsTab;
    @Inject private DropLogTab dropLogTab;
    @Inject private PartiesTab partiesTab;

    private NavigationButton navButton;
    private ScheduledFuture<?> dropRefresh;
    private ScheduledFuture<?> badgeRefresh;

    @Provides
    FinalBossConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(FinalBossConfig.class);
    }

    @Override
    protected void startUp()
    {
        clan.activate();
        clan.setListener(this::onStatus);
        content.resetSession();
        pbs.resetSession();

        // Startup fetches, all off the client thread.
        executor.submit(dropRates::load);
        executor.submit(content::refreshNotableItems);
        executor.submit(() -> {
            content.refreshWelcome();
            content.maybeShowWelcome();
        });
        // Warms the cache and populates the tab before it's first opened.
        announcementsTab.refresh();

        navButton = NavigationButton.builder()
            .tooltip("Final Boss")
            .icon(ImageUtil.loadImageResource(getClass(), "icon.png"))
            .priority(10)
            .panel(sidebar)
            .build();
        toolbar.addNavigation(navButton);

        // Enabled mid-session: no LOGGED_IN event will fire.
        clientThread.invokeLater(() -> {
            if (client.getGameState() == GameState.LOGGED_IN) clan.verifyAfter(0);
        });
    }

    @Override
    protected void shutDown()
    {
        clan.deactivate();
        stopPolling();
        toolbar.removeNavigation(navButton);
    }

    private void onStatus(Clan.Status status)
    {
        long generation = clan.snapshot().getGeneration();
        SwingUtilities.invokeLater(() -> {
            if (clan.snapshot().getGeneration() != generation) return;
            sidebar.show(status);
            if (status == Clan.Status.MEMBER)
            {
                sidebar.refreshActiveTab();
            }
        });
        if (status != Clan.Status.MEMBER)
        {
            return;
        }
        startPolling();
        executor.submit(content::maybeShowWelcome);
        // World-type and varp reads belong on the client thread.
        clientThread.invokeLater(() -> {
            pbs.maybeSeed();
            stats.maybeSubmit();
            executor.submit(drops::flush);
        });
    }

    private void startPolling()
    {
        parties.start();
        if (config.enableDropLogging() && dropRefresh == null)
        {
            dropRefresh = executor.scheduleAtFixedRate(() -> {
                try
                {
                    dropLogTab.refresh();
                }
                catch (Exception e)
                {
                    log.warn("Drop refresh error", e);
                }
            }, 60, 60, TimeUnit.SECONDS);
        }
        // Badge tiers: fetch on verification, then every 5 minutes so
        // newly earned tiers show without a relog.
        if (badgeRefresh != null)
        {
            return;
        }
        badgeRefresh = executor.scheduleAtFixedRate(() -> {
            try
            {
                badges.refresh();
            }
            catch (Exception e)
            {
                log.warn("CA badge refresh error", e);
            }
        }, 0, 300, TimeUnit.SECONDS);
    }

    private void stopPolling()
    {
        parties.stop();
        SwingUtilities.invokeLater(partiesTab::reset);
        killcounts.clear();
        if (dropRefresh != null)
        {
            dropRefresh.cancel(true);
            dropRefresh = null;
        }
        if (badgeRefresh != null)
        {
            badgeRefresh.cancel(true);
            badgeRefresh = null;
        }
    }

    // ------------------------------------------------------------ events

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            if (!clan.isVerified())
            {
                // Let the login flow settle before reading the player name.
                clan.verifyAfter(3);
            }
        }
        else if (event.getGameState() == GameState.LOGIN_SCREEN && (clan.isVerified() || clan.rsn() != null))
        {
            clan.reset();
            pbs.resetSession();
            content.resetSession();
            stopPolling();
            SwingUtilities.invokeLater(() -> sidebar.show(Clan.Status.VERIFYING));
        }
    }

    @Subscribe
    public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
    {
        clan.reset();
        pbs.resetSession();
        content.resetSession();
        stopPolling();
        if (client.getGameState() == GameState.LOGGED_IN) clan.verifyAfter(1);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"finalboss".equals(event.getGroup())) return;
        clientThread.invokeLater(() -> {
            stopPolling();
            if (clan.isVerified()) startPolling();
        });
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getTickCount() % 50 == 0)
        {
            pbs.maybeSeed();
            stats.maybeSubmit();
            executor.submit(drops::flush);
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        // Collection log count is a varp; CA points a varbit.
        if (event.getVarpId() == VarPlayerID.COLLECTION_COUNT || event.getVarbitId() == VarbitID.CA_POINTS)
        {
            stats.maybeSubmit();
        }
    }

    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event)
    {
        drops.onLoot(event.getNpc().getName(), event.getItems());
    }

    // Loot with no NPC kill behind it: raid chests, Barrows, and the few
    // bosses whose reward-chest loot the Loot Tracker reports as an NPC
    // record without an NPC-kill event (Gauntlet, Whisperer, Araxxor,
    // Royal Titans). Requires the core Loot Tracker plugin (on by default).
    @Subscribe
    public void onLootReceived(LootReceived event)
    {
        boolean chestNpc = event.getType() == LootRecordType.NPC && DropRules.CHEST_LOOT_NPCS.contains(event.getName());
        if (event.getType() == LootRecordType.EVENT || chestNpc)
        {
            drops.onLoot(event.getName(), event.getItems(), true);
        }
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        pbs.onChatMessage(event);
        drops.onChatMessage(event);
        if (config.enableChatBadges())
        {
            badges.onChatMessage(event);
        }
        lfgCommand.onChatMessage(event);
    }
}

package com.github.orgonag.fbclan.stats;

import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.game.ChatIconManager;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

/**
 * Prepends a combat-achievement slayer helmet (Tztok = Elite, Vampyric
 * = Master, Tzkal = Grandmaster) to clan members' names in chat. Tiers
 * come from the same read-only ca_leaderboard view the dashboard uses,
 * so only members who upload stats get a badge.
 */
@Singleton
public class CaBadges
{
    private static final Set<ChatMessageType> BADGED = EnumSet.of(
        ChatMessageType.PUBLICCHAT, ChatMessageType.MODCHAT, ChatMessageType.PRIVATECHAT,
        ChatMessageType.PRIVATECHATOUT, ChatMessageType.MODPRIVATECHAT, ChatMessageType.FRIENDSCHAT,
        ChatMessageType.CLAN_CHAT, ChatMessageType.CLAN_GUEST_CHAT, ChatMessageType.CLAN_GIM_CHAT);

    private final Supabase db;
    private final ChatIconManager icons;
    private final Map<String, Integer> iconByTier = new HashMap<>();
    private volatile Map<String, String> tierByRsn = Collections.emptyMap();

    @Inject
    public CaBadges(Supabase db, ChatIconManager icons)
    {
        this.db = db;
        this.icons = icons;
    }

    // Icons are registered on first use, not at injection time, so a
    // loaded-but-disabled plugin registers nothing.
    private synchronized void ensureIcons()
    {
        if (iconByTier.isEmpty())
        {
            iconByTier.put("Elite", register("ca_elite.png"));
            iconByTier.put("Master", register("ca_master.png"));
            iconByTier.put("Grandmaster", register("ca_grandmaster.png"));
        }
    }

    private int register(String resource)
    {
        BufferedImage image = ImageUtil.loadImageResource(CaBadges.class, "/com/github/orgonag/fbclan/" + resource);
        return icons.registerChatIcon(image);
    }

    // Executor.
    public void refresh()
    {
        JsonArray rows = db.getOrNull("member_badges", "select=rsn,tier&order=rsn.asc");
        if (rows == null)
        {
            return; // keep the previous tiers through an outage
        }
        Map<String, String> tiers = new HashMap<>();
        for (JsonElement el : rows)
        {
            JsonObject row = el.getAsJsonObject();
            String rsn = Text.standardize(Supabase.str(row, "rsn"));
            String tier = Supabase.str(row, "tier");
            if (!rsn.isEmpty() && !tier.isEmpty())
            {
                tiers.put(rsn, tier);
            }
        }
        tierByRsn = Collections.unmodifiableMap(tiers);
    }

    // Client thread. Chat names carry img tags and non-breaking spaces;
    // Text.standardize strips both, matching how the stored RSNs are keyed.
    public void onChatMessage(ChatMessage event)
    {
        if (!BADGED.contains(event.getType()) || event.getName() == null)
        {
            return;
        }
        ensureIcons();
        Integer icon = iconByTier.get(tierByRsn.get(Text.standardize(event.getName())));
        if (icon == null)
        {
            return;
        }
        int index = icons.chatIconIndex(icon);
        if (index < 0)
        {
            return; // mod icon sprites not loaded yet (pre-login)
        }
        MessageNode node = event.getMessageNode();
        node.setName("<img=" + index + ">" + node.getName());
    }
}

package com.github.orgonag.fbclan.stats;

import com.github.orgonag.fbclan.FinalBossConfig;
import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.core.Session;
import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonObject;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Uploads the member's collection-log count and combat-achievement
 * points through the improve-only submit_stats function. Varps/varbits
 * are read on the client thread (verification success and varb changes);
 * the submit runs on the executor. Values only ever rise, so a
 * resubmission happens only when a counter passes the last sent value.
 */
@Singleton
public class MemberStats
{
    private final Client client;
    private final FinalBossConfig config;
    private final Clan clan;
    private final Supabase db;
    private final ScheduledExecutorService executor;

    private volatile String acknowledged;
    private final java.util.concurrent.atomic.AtomicBoolean sending = new java.util.concurrent.atomic.AtomicBoolean();

    @Inject
    public MemberStats(Client client, FinalBossConfig config, Clan clan, Supabase db, ScheduledExecutorService executor)
    {
        this.client = client;
        this.config = config;
        this.clan = clan;
        this.db = db;
        this.executor = executor;
    }

    // Client thread (varp reads assert it under -ea).
    public void maybeSubmit()
    {
        Session session = clan.snapshot();
        if (!clan.canUpload() || !config.enableStatsUpload() || !clan.onStandardWorld())
        {
            return;
        }
        int clObtained = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
        int clTotal = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
        int caPoints = client.getVarbitValue(VarbitID.CA_POINTS);
        if ((clObtained <= 0 && caPoints <= 0))
        {
            return;
        }
        String tier = tierFor(caPoints, thresholds());
        String signature = session.getGeneration() + ":" + clObtained + ":" + clTotal + ":" + caPoints + ":" + tier;
        if (signature.equals(acknowledged) || !sending.compareAndSet(false, true)) return;
        executor.submit(() -> {
            try
            {
                if (clan.current(session) && config.enableStatsUpload() && submit(session.getRsn(), clObtained, clTotal, caPoints, tier)
                    && clan.current(session)) acknowledged = signature;
            }
            finally { sending.set(false); }
        });
    }

    private boolean submit(String rsn, int clObtained, int clTotal, int caPoints, String tier)
    {
        // Fields the client can't read yet are omitted; the RPC treats an
        // absent field as "no update".
        JsonObject p = new JsonObject();
        p.addProperty("p_rsn", rsn);
        boolean hasCl = clObtained > 0 && clTotal >= clObtained;
        boolean hasCa = caPoints > 0;
        if (hasCl)
        {
            p.addProperty("p_cl_obtained", clObtained);
            p.addProperty("p_cl_total", clTotal);
        }
        if (hasCa)
        {
            p.addProperty("p_ca_points", caPoints);
            if (tier != null)
            {
                p.addProperty("p_ca_tier", tier);
            }
        }
        return (hasCl || hasCa) && db.rpc("fb_submit_stats", p);
    }

    // Tier cutoffs read live from the game (Dink pattern) so new tasks
    // re-scale without a plugin update. Null = below Easy.
    private static String tierFor(int points, TreeMap<Integer, String> thresholds)
    {
        Map.Entry<Integer, String> e = thresholds.floorEntry(points);
        return e == null ? null : e.getValue();
    }

    private TreeMap<Integer, String> thresholds()
    {
        TreeMap<Integer, String> t = new TreeMap<>();
        put(t, VarbitID.CA_THRESHOLD_EASY, "Easy");
        put(t, VarbitID.CA_THRESHOLD_MEDIUM, "Medium");
        put(t, VarbitID.CA_THRESHOLD_HARD, "Hard");
        put(t, VarbitID.CA_THRESHOLD_ELITE, "Elite");
        put(t, VarbitID.CA_THRESHOLD_MASTER, "Master");
        put(t, VarbitID.CA_THRESHOLD_GRANDMASTER, "Grandmaster");
        return t;
    }

    private void put(TreeMap<Integer, String> map, int varbit, String tier)
    {
        int value = client.getVarbitValue(varbit);
        if (value > 0)
        {
            map.put(value, tier);
        }
    }
}

package com.github.orgonag.fbclan.stats;

import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;

/**
 * Read side of the clan dashboard: collection-log and combat-achievement
 * top-20s (member uploads), GP this week (logged drops), and the weekly
 * Wise Old Man podiums served from the wom_cache table (an hourly sync
 * script fills it; the plugin never calls WOM for this). Every source
 * fails soft independently, keeping last-known data.
 */
@Singleton
public class Dashboard
{
    @Value
    public static class Named
    {
        String rsn;
        double value;
    }

    @Value
    public static class ClEntry
    {
        String rsn;
        int obtained;
        int total;
    }

    @Value
    public static class CaEntry
    {
        String rsn;
        int points;
        String tier;
    }

    @Value
    public static class GpWeek
    {
        long totalGp;
        int dropCount;
        List<Named> top;
    }

    private final Supabase db;

    private volatile List<ClEntry> clBoard = Collections.emptyList();
    private volatile List<CaEntry> caBoard = Collections.emptyList();
    private volatile GpWeek gpWeek = new GpWeek(0, 0, Collections.emptyList());
    private volatile List<Named> xpWeek;   // null until the WOM cache is read
    private volatile List<Named> ehbWeek;
    private volatile String womSyncedAt = "";

    @Inject
    public Dashboard(Supabase db)
    {
        this.db = db;
    }

    public List<ClEntry> clBoard()
    {
        return clBoard;
    }

    public List<CaEntry> caBoard()
    {
        return caBoard;
    }

    public GpWeek gpWeek()
    {
        return gpWeek;
    }

    public List<Named> xpWeek()
    {
        return xpWeek;
    }

    public List<Named> ehbWeek()
    {
        return ehbWeek;
    }

    public String womSyncedAt()
    {
        return womSyncedAt;
    }

    // Executor. Each source fails soft independently, keeping its
    // previous value; an empty result is real and clears it.
    public boolean refresh()
    {
        JsonArray cl = db.getOrNull("cl_leaderboard", "select=rsn,cl_obtained,cl_total&order=cl_obtained.desc,rsn.asc");
        if (cl != null)
        {
            List<ClEntry> out = new ArrayList<>();
            for (JsonElement el : cl)
            {
                JsonObject r = el.getAsJsonObject();
                if (!Supabase.str(r, "rsn").isEmpty() && Supabase.has(r, "cl_obtained") && Supabase.has(r, "cl_total"))
                {
                    out.add(new ClEntry(Supabase.str(r, "rsn"), Supabase.intOr(r,"cl_obtained",0), Supabase.intOr(r,"cl_total",0)));
                }
            }
            clBoard = Collections.unmodifiableList(out);
        }
        JsonArray ca = db.getOrNull("ca_leaderboard", "select=rsn,ca_points,tier&order=ca_points.desc,rsn.asc");
        if (ca != null)
        {
            List<CaEntry> out = new ArrayList<>();
            for (JsonElement el : ca)
            {
                JsonObject r = el.getAsJsonObject();
                if (!Supabase.str(r, "rsn").isEmpty() && Supabase.has(r, "ca_points"))
                {
                    out.add(new CaEntry(Supabase.str(r, "rsn"), Supabase.intOr(r,"ca_points",0), Supabase.str(r, "tier")));
                }
            }
            caBoard = Collections.unmodifiableList(out);
        }
        JsonArray total = db.getOrNull("gp_week_total", "select=total_gp,drop_count");
        JsonArray top = db.getOrNull("gp_week_top", "select=rsn,gp&order=gp.desc,rsn.asc");
        if (total != null && top != null)
        {
            JsonObject t = total.size() > 0 ? total.get(0).getAsJsonObject() : new JsonObject();
            List<Named> names = new ArrayList<>();
            for (JsonElement el : top)
            {
                JsonObject r = el.getAsJsonObject();
                if (!Supabase.str(r, "rsn").isEmpty() && Supabase.has(r, "gp"))
                {
                    names.add(new Named(Supabase.str(r, "rsn"), Supabase.doubleOr(r,"gp",0)));
                }
            }
            gpWeek = new GpWeek(Supabase.longOr(t, "total_gp", 0), Supabase.intOr(t, "drop_count", 0),
                Collections.unmodifiableList(names));
        }
        JsonArray wom = db.getOrNull("wom_cache", "select=metric,payload,updated_at");
        if (wom != null)
        {
            applyWomCache(wom);
        }
        return cl != null && ca != null && total != null && top != null && wom != null;
    }

    // Each row's payload is the raw WOM response array for one metric.
    private void applyWomCache(JsonArray rows)
    {
        xpWeek = Collections.emptyList();
        ehbWeek = Collections.emptyList();
        womSyncedAt = "";
        String newest = "";
        for (JsonElement el : rows)
        {
            if (!el.isJsonObject()) continue;
            JsonObject row = el.getAsJsonObject();
            String metric = Supabase.str(row, "metric");
            if (metric.isEmpty() || !Supabase.has(row, "payload") || !row.get("payload").isJsonArray())
            {
                continue;
            }
            String updated = Supabase.str(row, "updated_at");
            if (updated.compareTo(newest) > 0)
            {
                newest = updated;
            }
            if ("gains_overall_week".equals(metric))
            {
                xpWeek = parseWom(row.getAsJsonArray("payload"), "gained");
            }
            else if ("gains_ehb_week".equals(metric))
            {
                ehbWeek = parseWom(row.getAsJsonArray("payload"), "gained");
            }
        }
        if (!newest.isEmpty())
        {
            womSyncedAt = newest;
        }
    }

    private static List<Named> parseWom(JsonArray rows, String valueKey)
    {
        List<Named> out = new ArrayList<>();
        for (JsonElement el : rows)
        {
            if (!el.isJsonObject()) continue;
            JsonObject row = el.getAsJsonObject();
            if (!Supabase.has(row, "player") || !Supabase.has(row, "data") || !row.get("player").isJsonObject() || !row.get("data").isJsonObject())
            {
                continue;
            }
            JsonObject player = row.getAsJsonObject("player");
            JsonObject data = row.getAsJsonObject("data");
            if (Supabase.has(player, "displayName") && Supabase.has(data, valueKey))
            {
                out.add(new Named(Supabase.str(player,"displayName"), Supabase.doubleOr(data,valueKey,0)));
            }
        }
        return Collections.unmodifiableList(out);
    }

    // ------------------------------------------------------------ formatting

    // 9_800_000 -> "9.8M", 14_200_000 -> "14M".
    public static String shortNumber(long n)
    {
        if (n >= 1_000_000_000L)
        {
            return unit(n, 1_000_000_000L) + "B";
        }
        if (n >= 1_000_000L)
        {
            return unit(n, 1_000_000L) + "M";
        }
        if (n >= 1_000L)
        {
            return unit(n, 1_000L) + "K";
        }
        return Long.toString(n);
    }

    public static String oneDecimal(double d)
    {
        return String.format(Locale.ROOT, "%.1f", d);
    }

    private static String unit(long n, long divisor)
    {
        double d = (double) n / divisor;
        if (d >= 10)
        {
            return Long.toString(n / divisor);
        }
        String s = String.format(Locale.ROOT, "%.1f", d);
        return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
    }
}

package com.github.orgonag.fbclan.drops;

import com.github.orgonag.fbclan.core.Session;
import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.ArrayList;
import java.util.List;

/** Disk I/O only on workers. One atomic file per event; no credentials stored. */
public final class DropOutbox
{
    private final Path directory;
    public DropOutbox(Path directory) { this.directory = directory; }
    public synchronized void add(Session session, JsonObject row) throws IOException
    {
        Files.createDirectories(directory);
        try (java.util.stream.Stream<Path> files = Files.list(directory))
        {
            if (files.filter(p -> p.toString().endsWith(".json")).count() >= 1000)
                throw new IOException("Drop outbox is full (1000 events)");
        }
        JsonObject record = new JsonObject();
        record.addProperty("profile", session.getProfile());
        record.addProperty("endpoint", Supabase.projectUrl());
        record.add("row", row);
        Path target = directory.resolve(Supabase.str(row, "event_id") + ".json");
        Path temporary = Files.createTempFile(directory, "event-", ".tmp");
        try
        {
            Files.write(temporary, record.toString().getBytes(StandardCharsets.UTF_8));
            try { Files.move(temporary, target, StandardCopyOption.ATOMIC_MOVE); }
            catch (AtomicMoveNotSupportedException e) { Files.move(temporary, target); }
        }
        finally { Files.deleteIfExists(temporary); }
    }
    public synchronized List<JsonObject> pending(Session session) throws IOException
    {
        List<JsonObject> out = new ArrayList<>();
        if (!Files.isDirectory(directory)) return out;
        try (DirectoryStream<Path> files = Files.newDirectoryStream(directory, "*.json"))
        {
            for (Path file : files)
            {
                try
                {
                    JsonObject record = new JsonParser().parse(Files.readString(file)).getAsJsonObject();
                    JsonObject row = record.getAsJsonObject("row");
                    if (session.getProfile().equals(Supabase.str(record, "profile"))
                        && Supabase.projectUrl().equals(Supabase.str(record, "endpoint"))
                        && com.github.orgonag.fbclan.core.Names.same(session.getRsn(), Supabase.str(row, "rsn"))) out.add(row);
                }
                catch (RuntimeException e) { Files.move(file, file.resolveSibling(file.getFileName() + ".invalid")); }
            }
        }
        return out;
    }
    public synchronized void reject(String id) throws IOException
    {
        Path file = directory.resolve(java.util.UUID.fromString(id) + ".json");
        Files.move(file, file.resolveSibling(file.getFileName() + ".rejected"), StandardCopyOption.REPLACE_EXISTING);
    }
    public synchronized void remove(String id) throws IOException
    {
        Files.deleteIfExists(directory.resolve(java.util.UUID.fromString(id) + ".json"));
    }
}

package com.github.orgonag.fbclan.drops;

import java.text.NumberFormat;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.OptionalDouble;
import java.util.Set;

/** What counts as a loggable drop. Pure rules; no I/O. */
public final class DropRules
{
    // Floor for the valuable threshold so nobody floods the shared log.
    public static final int MIN_THRESHOLD_GP = 1_000_000;

    // Chat lines the game prints for a pet (pets never appear in loot
    // events); the same set the core Screenshot plugin matches.
    private static final String PET_FOLLOWER = "You have a funny feeling like you're being followed";
    private static final String PET_BACKPACK = "You feel something weird sneaking into your backpack";
    private static final String PET_DUPLICATE = "You have a funny feeling like you would have been followed";

    // Loot the core Loot Tracker reports as an NPC record with no NPC-kill
    // event (it comes from a reward chest): picked up from the tracker's
    // own event instead. Same list Dink keeps.
    public static final String GAUNTLET_BOSS = "Crystalline Hunllef";
    public static final String CORRUPTED_GAUNTLET_BOSS = "Corrupted Hunllef";
    public static final String GAUNTLET = "The Gauntlet";
    public static final String CORRUPTED_GAUNTLET = "The Corrupted Gauntlet";
    public static final Set<String> CHEST_LOOT_NPCS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
        GAUNTLET_BOSS, CORRUPTED_GAUNTLET_BOSS, "The Whisperer", "Araxxor",
        "Branda the Fire Queen", "Eldric the Ice King")));

    private DropRules()
    {
    }

    public static long threshold(long configuredGp)
    {
        return Math.max(configuredGp, MIN_THRESHOLD_GP);
    }

    public static boolean valuable(long totalValue, long thresholdGp)
    {
        return totalValue >= thresholdGp;
    }

    // 1 in `denominator` or rarer; 0 disables; unknown never qualifies.
    public static boolean rare(OptionalDouble rarity, int denominator)
    {
        return denominator > 0 && rarity.isPresent() && rarity.getAsDouble() <= 1.0 / denominator;
    }

    // Never logged by the automatic rules regardless of value or rate:
    // clue scrolls, long/curved bones, champion scrolls, and keys. The
    // clan's notable list is an explicit choice and bypasses this.
    public static boolean neverLogged(String itemName)
    {
        if (itemName == null)
        {
            return false;
        }
        String n = itemName.toLowerCase(Locale.ROOT).trim();
        return n.startsWith("clue scroll")
            || n.equals("long bone")
            || n.equals("curved bone")
            || n.endsWith("champion scroll")
            || n.endsWith(" key")
            || n.endsWith(" half of key")
            || n.contains(" key (");
    }

    // The Gauntlet's loot is logged under the activity, not the boss.
    public static String displaySource(String lootSource)
    {
        if (GAUNTLET_BOSS.equals(lootSource))
        {
            return GAUNTLET;
        }
        if (CORRUPTED_GAUNTLET_BOSS.equals(lootSource))
        {
            return CORRUPTED_GAUNTLET;
        }
        return lootSource;
    }

    public static boolean isPetMessage(String message)
    {
        return message != null
            && (message.contains(PET_FOLLOWER) || message.contains(PET_BACKPACK) || message.contains(PET_DUPLICATE));
    }

    // The only variant where the new pet is readable off getFollower().
    public static boolean isFollowerPet(String message)
    {
        return message != null && message.contains(PET_FOLLOWER);
    }

    public static boolean isDuplicatePet(String message)
    {
        return message != null && message.contains(PET_DUPLICATE);
    }

    public static String formatGp(long value)
    {
        return NumberFormat.getIntegerInstance(Locale.US).format(value);
    }

    // "1/512", rounded to the nearest whole denominator.
    public static String formatRarity(double probability)
    {
        return probability <= 0 ? "" : "1/" + Math.round(1 / probability);
    }
}

package com.github.orgonag.fbclan.drops;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import com.google.gson.reflect.TypeToken;
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.OptionalDouble;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;

/**
 * "How rare is item X from source Y?" Backed by the bundled npc_drops.json:
 * the OSRS Wiki's monster drop tables (CC BY-NC-SA 3.0), parsed by
 * Flipping Utilities' parsed-osrs and compacted by the Dink plugin
 * (BSD-2-Clause, (c) Jake Barter). Lookup logic mirrors Dink's. A small
 * in-code supplement covers reward chests the wiki table lacks.
 *
 * Loaded once on the executor (~700 KB); lookups before that report
 * "unknown" rather than blocking.
 */
@Slf4j
@Singleton
public class DropRates
{
    private static final String RESOURCE = "/com/github/orgonag/fbclan/npc_drops.json";

    private final ItemManager itemManager;
    private final Gson gson;
    private volatile Map<String, Collection<Drop>> bySource = Collections.emptyMap();

    @Inject
    public DropRates(ItemManager itemManager, Gson gson)
    {
        this.itemManager = itemManager;
        this.gson = gson; // Plugin Hub forbids fresh Gson instances; use the client's
    }

    public void load()
    {
        if (!bySource.isEmpty())
        {
            return; // already parsed this client session
        }
        Map<String, List<RawDrop>> raw;
        try (InputStream is = DropRates.class.getResourceAsStream(RESOURCE);
             Reader reader = new BufferedReader(new InputStreamReader(
                 Objects.requireNonNull(is, "missing " + RESOURCE), StandardCharsets.UTF_8)))
        {
            raw = gson.fromJson(reader, new TypeToken<Map<String, List<RawDrop>>>() {}.getType());
        }
        catch (Exception e)
        {
            log.error("Failed to read drop rate table", e);
            return;
        }
        Map<String, Collection<Drop>> table = new HashMap<>(raw.size() * 2);
        raw.forEach((source, drops) -> {
            List<Drop> out = new ArrayList<>();
            for (RawDrop r : drops)
            {
                out.addAll(r.expand());
            }
            table.put(source, out);
        });
        // Reward chests: rates from the OSRS Wiki's Gauntlet reward pages.
        // Item ids: enhanced crystal weapon seed, crystal armour seed,
        // crystal weapon seed.
        table.put(DropRules.GAUNTLET, Arrays.asList(
            new Drop(25859, 1, 1, 1.0 / 2000), new Drop(23956, 1, 1, 1.0 / 120), new Drop(4207, 1, 1, 1.0 / 120)));
        table.put(DropRules.CORRUPTED_GAUNTLET, Arrays.asList(
            new Drop(25859, 1, 1, 1.0 / 400), new Drop(23956, 1, 1, 1.0 / 50), new Drop(4207, 1, 1, 1.0 / 50)));
        bySource = table;
        log.info("Loaded drop rates for {} sources", table.size());
    }

    // Probability (0..1) that one kill/completion of `source` yields this
    // item stack, or empty when unknown. Noted items resolve to the
    // unnoted id; charged/ornamented variants match by shared name.
    public OptionalDouble rarity(String source, int itemId, int quantity)
    {
        Collection<Drop> drops = bySource.get(source);
        if (drops == null || drops.isEmpty())
        {
            return OptionalDouble.empty();
        }
        ItemComposition comp = itemId >= 0 ? itemManager.getItemComposition(itemId) : null;
        int canonical = comp != null && comp.getNote() != -1 ? comp.getLinkedNoteId() : itemId;
        String itemName = comp != null ? comp.getMembersName() : "";
        Collection<Integer> variants = new HashSet<>(
            ItemVariationMapping.getVariations(ItemVariationMapping.map(canonical)));

        double total = 0;
        boolean any = false;
        for (Drop d : drops)
        {
            if (quantity < d.minQuantity || quantity > d.maxQuantity)
            {
                continue;
            }
            boolean match = d.itemId == itemId
                || (variants.contains(d.itemId)
                    && itemName.equals(itemManager.getItemComposition(d.itemId).getMembersName()));
            if (match)
            {
                total += d.probability;
                any = true;
            }
        }
        return any ? OptionalDouble.of(total) : OptionalDouble.empty();
    }

    @Value
    private static class Drop
    {
        int itemId;
        int minQuantity;
        int maxQuantity;
        double probability;
    }

    // One line of npc_drops.json: item id, denominator (1/d per roll),
    // optional roll count, and a fixed quantity or a min..max range.
    private static class RawDrop
    {
        @SerializedName("i") int itemId;
        @SerializedName("r") Integer rolls;
        @SerializedName("d") double denominator;
        @SerializedName("q") Integer quantity;
        @SerializedName("m") Integer quantMin;
        @SerializedName("n") Integer quantMax;

        // Multi-roll tables become one entry per possible success count,
        // each with the binomial probability of exactly that many hits.
        Collection<Drop> expand()
        {
            int rounds = rolls != null ? rolls : 1;
            int min = quantMin != null ? quantMin : (quantity != null ? quantity : 1);
            int max = quantMax != null ? quantMax : (quantity != null ? quantity : 1);
            double p = denominator > 0 ? 1 / denominator : 0;
            if (rounds <= 1)
            {
                return Collections.singletonList(new Drop(itemId, min, max, p));
            }
            List<Drop> out = new ArrayList<>(rounds);
            for (int k = 1; k <= rounds; k++)
            {
                out.add(new Drop(itemId, min * k, max * k, binomial(p, rounds, k)));
            }
            return out;
        }

        private static double binomial(double p, int n, int k)
        {
            double coeff = 1;
            for (int i = 1; i <= k; i++)
            {
                coeff = coeff * (n - k + i) / i;
            }
            return coeff * Math.pow(p, k) * Math.pow(1 - p, n - k);
        }
    }
}

package com.github.orgonag.fbclan.drops;
import java.util.HashMap;
import java.util.Map;

/** Match overlapping event channels without collapsing two identical NPC kills. Client thread only. */
public final class LootDeduplicator
{
    private int tick = -1;
    private final Map<String,int[]> counts = new HashMap<>();
    public boolean accept(int currentTick, String fingerprint, boolean tracker)
    {
        if (tick != currentTick) { counts.clear(); tick = currentTick; }
        int[] seen = counts.computeIfAbsent(fingerprint, key -> new int[2]);
        int own = tracker ? 1 : 0;
        return ++seen[own] > seen[1-own];
    }
}

