/**
 * The clan dashboard: seven collapsible sections (weekly WOM podiums,
 * collection log and CA top-20s, new clan bests, all-time PBs, GP this
 * week). Shiny bits are painted, not font glyphs (the RuneScape font
 * has no medals). Expansion state lives for the session.
 */
@Singleton
public class LeaderboardsTab extends JPanel
{
    private static final String[] SECTIONS = {
        "XP Gained This Week", "EHB This Week", "Collection Log", "Combat Achievements",
        "New Clan Bests", "All-Time PBs", "GP This Week",
    };

    private final Leaderboards pbs;
    private final Dashboard dashboard;
    private final ScheduledExecutorService executor;
    private final JPanel list;
    private final javax.swing.JTextArea refreshError = Ui.plain("");
    private final java.util.concurrent.atomic.AtomicBoolean refreshing = new java.util.concurrent.atomic.AtomicBoolean();
    private final boolean[] expanded = {true, true, true, true, false, false, false};
    private final Set<String> openBosses = new HashSet<>();

    @Inject
    public LeaderboardsTab(Leaderboards pbs, Dashboard dashboard, ScheduledExecutorService executor)
    {
        this.pbs = pbs;
        this.dashboard = dashboard;
        this.executor = executor;
        setLayout(new BorderLayout());
        add(refreshError, BorderLayout.NORTH);
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        list = Ui.scrollList(this);
        list.setBorder(BorderFactory.createEmptyBorder(5, 8, 5, 8));
        render();
    }

    public void refresh()
    {
        if (!refreshing.compareAndSet(false, true)) return;
        Ui.async(executor, () -> {
            boolean ok = pbs.refresh();
            ok = dashboard.refresh() && ok;
            if (!ok) throw new IllegalStateException("Some sources could not refresh");
            return null;
        }, v -> { refreshing.set(false); render(); }, message -> { if (message != null) refreshing.set(false); refreshError.setText(message == null ? "" : message); });
    }

    private void render()
    {
        list.removeAll();
        for (int i = 0; i < SECTIONS.length; i++)
        {
            int index = i;
            list.add(toggle(SECTIONS[i], expanded[i], () -> {
                expanded[index] = !expanded[index];
                render();
            }, true));
            if (expanded[i])
            {
                JPanel content = Ui.column(ColorScheme.DARK_GRAY_COLOR);
                content.setBorder(BorderFactory.createEmptyBorder(4, 0, 8, 0));
                section(i, content);
                list.add(content);
            }
        }
        list.revalidate();
        list.repaint();
    }

    private void section(int index, JPanel content)
    {
        switch (index)
        {
            case 0:
                podium(content, dashboard.xpWeek(), v -> Dashboard.shortNumber((long) v), "via Wise Old Man" + synced());
                break;
            case 1:
                podium(content, dashboard.ehbWeek(), Dashboard::oneDecimal, "efficient hours bossed" + synced());
                break;
            case 2:
                if (dashboard.clBoard().isEmpty())
                {
                    content.add(Ui.empty("No collection logs uploaded yet."));
                }
                int rank = 1;
                for (Dashboard.ClEntry e : dashboard.clBoard())
                {
                    content.add(statRow(rank++, e.getRsn(), null, String.format("%,d/%,d", e.getObtained(), e.getTotal())));
                }
                break;
            case 3:
                if (dashboard.caBoard().isEmpty())
                {
                    content.add(Ui.empty("No combat achievements uploaded yet."));
                }
                int r = 1;
                for (Dashboard.CaEntry e : dashboard.caBoard())
                {
                    content.add(statRow(r++, e.getRsn(), e.getTier(), String.format("%,d", e.getPoints())));
                }
                break;
            case 4:
                if (pbs.recent().isEmpty())
                {
                    content.add(Ui.empty("No new clan bests yet."));
                }
                for (Entry e : pbs.recent())
                {
                    content.add(recentRow(e));
                }
                break;
            case 5:
                allTimePbs(content);
                break;
            case 6:
                gpWeek(content);
                break;
        }
    }

    private void podium(JPanel content, List<Named> entries, DoubleFunction<String> fmt, String caption)
    {
        if (entries == null)
        {
            content.add(Ui.empty("waiting for WOM sync"));
            return;
        }
        if (entries.isEmpty())
        {
            content.add(Ui.empty("No data this week."));
            return;
        }
        List<String> names = new ArrayList<>();
        List<String> values = new ArrayList<>();
        for (Named e : entries)
        {
            names.add(e.getRsn());
            values.add(fmt.apply(e.getValue()));
        }
        content.add(new Podium(names, values));
        content.add(caption(caption));
    }

    private void gpWeek(JPanel content)
    {
        Dashboard.GpWeek gp = dashboard.gpWeek();
        JLabel total = Ui.small("Clan total: " + Dashboard.shortNumber(gp.getTotalGp()) + " GP · " + gp.getDropCount() + " drops", Ui.GOLD);
        total.setBorder(BorderFactory.createEmptyBorder(0, 6, 4, 0));
        content.add(total);
        if (gp.getTop().isEmpty())
        {
            content.add(Ui.empty("No logged drops in the last 7 days."));
            return;
        }
        List<String> names = new ArrayList<>();
        List<String> values = new ArrayList<>();
        for (Named e : gp.getTop())
        {
            names.add(e.getRsn());
            values.add(Dashboard.shortNumber((long) e.getValue()));
        }
        content.add(new Podium(names, values));
        content.add(caption("logged drops (1M+/notables) · last 7 days"));
    }

    private void allTimePbs(JPanel content)
    {
        if (pbs.board().isEmpty())
        {
            content.add(Ui.empty("No personal bests recorded yet."));
            return;
        }
        Map<String, List<Entry>> byBoss = new LinkedHashMap<>();
        for (Entry e : pbs.board())
        {
            byBoss.computeIfAbsent(e.getBossKey(), k -> new ArrayList<>()).add(e);
        }
        Map<String, String> sorted = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
        for (String key : byBoss.keySet())
        {
            sorted.put(PbParser.displayName(key), key);
        }
        for (Map.Entry<String, String> e : sorted.entrySet())
        {
            String boss = e.getValue();
            boolean open = openBosses.contains(boss);
            content.add(toggle(e.getKey(), open, () -> {
                if (!openBosses.remove(boss))
                {
                    openBosses.add(boss);
                }
                render();
            }, false));
            if (open)
            {
                for (Entry entry : byBoss.get(boss))
                {
                    content.add(statRow(entry.getRank(), entry.getRsn(), null, PbParser.formatSeconds(entry.getSeconds())));
                }
            }
        }
    }

    private String synced()
    {
        String at = dashboard.womSyncedAt();
        String ago = at.isEmpty() ? "" : Ui.timeAgo(at);
        return ago.isEmpty() ? "" : " · synced " + ago;
    }

    // ------------------------------------------------------------ rows

    private static JPanel statRow(int rank, String rsn, String tier, String value)
    {
        JPanel row = Ui.row(ColorScheme.DARK_GRAY_COLOR);
        row.setBorder(BorderFactory.createEmptyBorder(2, 8, 2, 6));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
        JLabel rankLabel = new JLabel();
        Medal medal = Medal.forRank(rank);
        if (medal != null)
        {
            rankLabel.setIcon(medal);
        }
        else
        {
            rankLabel.setText(Integer.toString(rank));
            rankLabel.setFont(FontManager.getRunescapeSmallFont());
            rankLabel.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
        }
        rankLabel.setPreferredSize(new Dimension(20, 16));
        row.add(rankLabel, BorderLayout.WEST);
        row.add(Ui.small(rsn, Ui.MUTED), BorderLayout.CENTER);
        JPanel east = new JPanel();
        east.setLayout(new javax.swing.BoxLayout(east, javax.swing.BoxLayout.X_AXIS));
        east.setBackground(ColorScheme.DARK_GRAY_COLOR);
        if (tier != null && !tier.isEmpty())
        {
            east.add(tierBadge(tier));
            east.add(Box.createRigidArea(new Dimension(5, 0)));
        }
        east.add(Ui.small(value, Ui.GOLD));
        row.add(east, BorderLayout.EAST);
        return row;
    }

    private static JPanel recentRow(Entry e)
    {
        JPanel row = Ui.row(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(BorderFactory.createEmptyBorder(3, 6, 3, 6));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));
        JPanel stack = Ui.column(ColorScheme.DARKER_GRAY_COLOR);
        stack.add(Ui.small(PbParser.displayName(e.getBossKey()) + " - " + PbParser.formatSeconds(e.getSeconds()), Ui.MUTED));
        stack.add(Ui.small(e.getRsn() + " · " + Ui.timeAgo(e.getAchievedAt()), ColorScheme.MEDIUM_GRAY_COLOR));
        row.add(stack, BorderLayout.CENTER);
        return row;
    }

    private static JLabel caption(String text)
    {
        JLabel l = Ui.small(text, ColorScheme.MEDIUM_GRAY_COLOR);
        l.setHorizontalAlignment(SwingConstants.CENTER);
        l.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
        l.setBorder(BorderFactory.createEmptyBorder(2, 0, 4, 0));
        return l;
    }

    // Clickable "+/-" header; `section` = bold orange, else small grey.
    private static JPanel toggle(String title, boolean open, Runnable onToggle, boolean section)
    {
        JPanel header = Ui.row(ColorScheme.DARKER_GRAY_COLOR);
        header.setBorder(section ? BorderFactory.createEmptyBorder(5, 6, 5, 6) : BorderFactory.createEmptyBorder(3, 6, 3, 6));
        header.setMaximumSize(new Dimension(Integer.MAX_VALUE, section ? 28 : 24));
        header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        JLabel label = new JLabel((open ? "- " : "+ ") + title);
        label.setFont(section ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeSmallFont());
        label.setForeground(section ? ColorScheme.BRAND_ORANGE : Ui.MUTED);
        header.add(label, BorderLayout.CENTER);
        header.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mousePressed(MouseEvent e)
            {
                onToggle.run();
            }
        });
        return header;
    }

    // GM cyan, Master red, Elite gold, others grey.
    private static JLabel tierBadge(String tier)
    {
        String text;
        Color color;
        switch (tier)
        {
            case "Grandmaster": text = "GM"; color = new Color(0x7df9ff); break;
            case "Master": text = "MASTER"; color = new Color(0xff6b6b); break;
            case "Elite": text = "ELITE"; color = Ui.GOLD; break;
            default: text = tier.toUpperCase(java.util.Locale.ROOT); color = ColorScheme.MEDIUM_GRAY_COLOR; break;
        }
        JLabel l = Ui.small(text, color);
        l.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(color, 1), BorderFactory.createEmptyBorder(0, 3, 0, 3)));
        return l;
    }

    // ------------------------------------------------------------ painted

    // Three-bar podium (2nd | 1st | 3rd), names above, values inside.
    private static class Podium extends JComponent
    {
        private static final int HEIGHT = 82;
        private static final int[] BAR = {56, 42, 32};
        private static final Color[][] COLORS = {
            {new Color(0xffd700), new Color(0xb8860b)},
            {new Color(0xd8d8d8), new Color(0x909090)},
            {new Color(0xd68a4a), new Color(0x8b4513)},
        };
        private static final int[] SLOT_TO_RANK = {1, 0, 2};
        private final String[] names;
        private final String[] values;

        Podium(List<String> names, List<String> values)
        {
            this.names = names.toArray(new String[0]);
            this.values = values.toArray(new String[0]);
            setPreferredSize(new Dimension(0, HEIGHT));
            setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
            setAlignmentX(LEFT_ALIGNMENT);
        }

        @Override
        protected void paintComponent(Graphics g)
        {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            int slotW = (getWidth() - 10) / 3;
            Font nameFont = FontManager.getRunescapeSmallFont();
            Font valueFont = nameFont.deriveFont(Font.BOLD);
            for (int slot = 0; slot < 3; slot++)
            {
                int rank = SLOT_TO_RANK[slot];
                if (rank >= names.length)
                {
                    continue;
                }
                int x = 2 + slot * (slotW + 3);
                int barY = HEIGHT - BAR[rank];
                g2.setPaint(new GradientPaint(x, barY, COLORS[rank][0], x, HEIGHT, COLORS[rank][1]));
                g2.fillRoundRect(x, barY, slotW, BAR[rank], 4, 4);
                g2.setFont(nameFont);
                FontMetrics fm = g2.getFontMetrics();
                g2.setColor(Ui.MUTED);
                String name = clip(names[rank], fm, slotW + 6);
                g2.drawString(name, x + (slotW - fm.stringWidth(name)) / 2, barY - 3);
                g2.setFont(valueFont);
                fm = g2.getFontMetrics();
                g2.setColor(new Color(0x1e1e1e));
                String value = clip(values[rank], fm, slotW);
                g2.drawString(value, x + (slotW - fm.stringWidth(value)) / 2, barY + fm.getAscent() + 2);
            }
            g2.dispose();
        }

        private static String clip(String s, FontMetrics fm, int maxW)
        {
            if (fm.stringWidth(s) <= maxW - 4)
            {
                return s;
            }
            String out = s;
            while (out.length() > 1 && fm.stringWidth(out + "..") > maxW - 4)
            {
                out = out.substring(0, out.length() - 1);
            }
            return out + "..";
        }
    }

    // 13px gold/silver/bronze medal with the rank numeral.
    private static class Medal implements Icon
    {
        private static final int SIZE = 13;
        private final Color light;
        private final Color dark;
        private final String numeral;

        static Medal forRank(int rank)
        {
            switch (rank)
            {
                case 1: return new Medal(new Color(0xffe97d), new Color(0xb8860b), "1");
                case 2: return new Medal(new Color(0xe8e8e8), new Color(0x808080), "2");
                case 3: return new Medal(new Color(0xe0a06a), new Color(0x8b4513), "3");
                default: return null;
            }
        }

        private Medal(Color light, Color dark, String numeral)
        {
            this.light = light;
            this.dark = dark;
            this.numeral = numeral;
        }

        @Override
        public void paintIcon(java.awt.Component c, Graphics g, int x, int y)
        {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setPaint(new GradientPaint(x, y, light, x + SIZE, y + SIZE, dark));
            g2.fillOval(x, y, SIZE - 1, SIZE - 1);
            g2.setColor(dark.darker());
            g2.drawOval(x, y, SIZE - 1, SIZE - 1);
            g2.setColor(new Color(0x1e1e1e));
            g2.setFont(c.getFont().deriveFont(Font.BOLD, 9f));
            FontMetrics fm = g2.getFontMetrics();
            g2.drawString(numeral, x + (SIZE - fm.stringWidth(numeral)) / 2, y + (SIZE + fm.getAscent() - fm.getDescent()) / 2);
            g2.dispose();
        }

        @Override
        public int getIconWidth()
        {
            return SIZE;
        }

        @Override
        public int getIconHeight()
        {
            return SIZE;
        }
    }
}

package com.github.orgonag.fbclan.ui;

import com.github.orgonag.fbclan.clan.ClanContent;
import com.github.orgonag.fbclan.clan.ClanContent.Announcement;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSeparator;
import javax.swing.JTextArea;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/** Clan announcements, full text, newest first. Plain text: nothing to inject. */
@Singleton
public class AnnouncementsTab extends JPanel
{
    private final ClanContent content;
    private final ScheduledExecutorService executor;
    private final JPanel list;
    private final javax.swing.JTextArea refreshError = Ui.plain("");
    private final java.util.concurrent.atomic.AtomicBoolean refreshing = new java.util.concurrent.atomic.AtomicBoolean();

    @Inject
    public AnnouncementsTab(ClanContent content, ScheduledExecutorService executor)
    {
        this.content = content;
        this.executor = executor;
        setLayout(new BorderLayout());
        add(refreshError, BorderLayout.NORTH);
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        list = Ui.scrollList(this);
        list.setBorder(BorderFactory.createEmptyBorder(5, 8, 5, 8));
        render(content.announcements());
    }

    public void refresh()
    {
        if (!refreshing.compareAndSet(false, true)) return;
        Ui.async(executor, () -> {
            if (!content.refreshAnnouncements()) throw new IllegalStateException("Refresh unavailable");
            return content.announcements();
        }, rows -> { refreshing.set(false); render(rows); }, message -> { if (message != null) refreshing.set(false); refreshError.setText(message == null ? "" : message); });
    }

    private void render(List<Announcement> items)
    {
        list.removeAll();
        if (items.isEmpty())
        {
            JLabel empty = Ui.empty("No announcements yet.");
            empty.setBorder(BorderFactory.createEmptyBorder(20, 0, 20, 0));
            list.add(empty);
        }
        for (int i = 0; i < items.size(); i++)
        {
            if (i > 0)
            {
                list.add(Box.createRigidArea(new Dimension(0, 8)));
                JSeparator sep = new JSeparator();
                sep.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
                sep.setAlignmentX(LEFT_ALIGNMENT);
                list.add(sep);
                list.add(Box.createRigidArea(new Dimension(0, 8)));
            }
            Announcement a = items.get(i);
            if (!a.getTitle().isEmpty())
            {
                JTextArea title = Ui.plain(a.getTitle());
                title.setFont(FontManager.getRunescapeBoldFont());
                title.setForeground(ColorScheme.BRAND_ORANGE);
                list.add(title);
            }
            if (!a.getDate().isEmpty())
            {
                JLabel date = Ui.small(a.getDate(), Ui.MUTED);
                date.setBorder(BorderFactory.createEmptyBorder(2, 0, 4, 0));
                list.add(date);
            }
            if (!a.getBody().isEmpty())
            {
                list.add(Ui.plain(a.getBody()));
            }
        }
        list.revalidate();
        list.repaint();
    }
}

package com.github.orgonag.fbclan.ui;

import com.github.orgonag.fbclan.FinalBossConfig;
import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.core.Names;
import com.github.orgonag.fbclan.lfg.Activity;
import com.github.orgonag.fbclan.lfg.FormedParty;
import com.github.orgonag.fbclan.lfg.Killcounts;
import com.github.orgonag.fbclan.lfg.LootRule;
import com.github.orgonag.fbclan.lfg.Party;
import com.github.orgonag.fbclan.lfg.Party.Applicant;
import com.github.orgonag.fbclan.lfg.PartyApi;
import com.github.orgonag.fbclan.lfg.PartyBoard;
import com.github.orgonag.fbclan.lfg.Role;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;

/**
 * The LFG tab: host a party, browse and apply, manage applicants, and
 * see recently formed parties. Renders whatever PartyBoard holds; every
 * write goes through the board (executor) and re-renders on the EDT.
 */
@Singleton
public class PartiesTab extends JPanel
{
    private final Clan clan;
    private final FinalBossConfig config;
    private final PartyBoard board;
    private final PartyApi api;
    private final Killcounts killcounts;
    private final ItemManager items;
    private final ScheduledExecutorService executor;

    private final JPanel list;
    private final HostForm form;
    private final JButton hostButton = new JButton("Host a party");
    private final JLabel error = Ui.small("", ColorScheme.PROGRESS_ERROR_COLOR);
    private final JComboBox<Object> filterBox;
    private boolean formVisible;
    private boolean editing;
    private String applyingId;
    private Activity filter;
    private boolean hideFull;
    private boolean showFormed;
    private String addMemberDraft = "";

    @Inject
    public PartiesTab(Clan clan, FinalBossConfig config, PartyBoard board, PartyApi api, Killcounts killcounts,
                      ItemManager items, ScheduledExecutorService executor)
    {
        this.clan = clan;
        this.config = config;
        this.board = board;
        this.api = api;
        this.killcounts = killcounts;
        this.items = items;
        this.executor = executor;
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        JPanel controls = Ui.column(ColorScheme.DARK_GRAY_COLOR);
        controls.setBorder(BorderFactory.createEmptyBorder(5, 5, 5, 5));
        hostButton.setAlignmentX(LEFT_ALIGNMENT);
        hostButton.addActionListener(e -> toggleForm());
        controls.add(Ui.pinHeight(hostButton));
        controls.add(Box.createRigidArea(new Dimension(0, 5)));

        form = new HostForm(killcounts, this::submitForm, () -> {
            formVisible = false;
            editing = false;
            render();
        });
        form.setVisible(false);
        controls.add(form);
        controls.add(Box.createRigidArea(new Dimension(0, 5)));

        List<Object> filters = new ArrayList<>();
        filters.add("All activities");
        Collections.addAll(filters, Activity.values());
        filterBox = new JComboBox<>(filters.toArray());
        filterBox.setRenderer(new Ui.ActivityRenderer());
        filterBox.setAlignmentX(LEFT_ALIGNMENT);
        filterBox.addActionListener(e -> {
            Object sel = filterBox.getSelectedItem();
            filter = sel instanceof Activity ? (Activity) sel : null;
            render();
        });
        controls.add(Ui.pinHeight(filterBox));
        JPanel toggles = new JPanel(new GridLayout(1, 2));
        toggles.setBackground(ColorScheme.DARK_GRAY_COLOR);
        toggles.setAlignmentX(LEFT_ALIGNMENT);
        JCheckBox hideFullBox = Ui.checkbox("Hide full");
        hideFullBox.setBackground(ColorScheme.DARK_GRAY_COLOR);
        hideFullBox.addActionListener(e -> {
            hideFull = hideFullBox.isSelected();
            render();
        });
        JCheckBox showFormedBox = Ui.checkbox("Show formed");
        showFormedBox.setBackground(ColorScheme.DARK_GRAY_COLOR);
        showFormedBox.setToolTipText("Parties that filled up in the last 7 days");
        showFormedBox.addActionListener(e -> {
            showFormed = showFormedBox.isSelected();
            render();
        });
        toggles.add(hideFullBox);
        toggles.add(showFormedBox);
        controls.add(Ui.pinHeight(toggles));
        error.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
        error.setVisible(false);
        controls.add(error);
        add(controls, BorderLayout.NORTH);
        list = Ui.scrollList(this);

        board.setListener(() -> SwingUtilities.invokeLater(this::render));
        render();
    }

    public void refresh()
    {
        executor.submit(board::refresh);
    }

    public void reset()
    {
        SwingUtilities.invokeLater(() -> {
            applyingId = null;
            applicationPanel = null;
            applicationShape = null;
            formVisible = false;
            editing = false;
            addMemberDraft = "";
            render();
        });
    }

    // ------------------------------------------------------------ host form

    private void toggleForm()
    {
        Party mine = board.mine();
        if (mine != null)
        {
            form.populate(mine);
            editing = true;
            formVisible = true;
        }
        else
        {
            formVisible = !formVisible;
            editing = false;
        }
        render();
    }

    private void submitForm()
    {
        String rsn = clan.rsn();
        if (rsn == null)
        {
            return;
        }
        try
        {
            Party draft = form.build(rsn, board.world());
            Party existing = editing ? board.mine() : null;
            Party party = existing == null ? draft : draft.toBuilder().id(existing.getId()).version(existing.getVersion()).build();
            board.run(() -> api.save(party), "Couldn't save your party. Refresh and try again.", message -> SwingUtilities.invokeLater(() -> {
                showError(message);
                if (message == null) { formVisible = false; editing = false; }
                render();
            }));
        }
        catch (IllegalArgumentException e) { showError(e.getMessage()); }

    }

    // ------------------------------------------------------------ render

    private void render()
    {
        String rsn = clan.rsn();
        if (board.refreshError() != null) { error.setText(board.refreshError()); error.setVisible(true); }
        Party mine = board.mine();
        form.setVisible(formVisible);
        form.setEditing(editing);
        form.setWorld(board.world());
        hostButton.setEnabled(!board.isBusy() && clan.canUpload() && config.enableLfg());
        hostButton.setText(mine != null ? "Edit your party" : formVisible ? "Hide form" : "Host a party");

        list.removeAll();
        if (mine != null)
        {
            list.add(Ui.header("Your party"));
            list.add(hostCard(mine));
        }
        List<Party> others = new ArrayList<>();
        for (Party p : board.parties())
        {
            boolean isMine = mine != null && p.getId().equals(mine.getId());
            boolean filtered = filter != null && p.getActivity() != filter;
            boolean hidden = hideFull && p.isFull() && p.applicantFor(rsn) == null;
            if (!isMine && !filtered && !hidden)
            {
                others.add(p);
            }
        }
        // Parties the player is in (or waiting on) float to the top.
        others.sort((a, b) -> {
            boolean ia = a.applicantFor(rsn) != null;
            boolean ib = b.applicantFor(rsn) != null;
            return ia != ib ? (ia ? -1 : 1) : b.getCreatedAt().compareTo(a.getCreatedAt());
        });
        if (mine != null)
        {
            list.add(Ui.header("Open parties (" + others.size() + ")"));
        }
        if (others.isEmpty())
        {
            list.add(Ui.empty(board.parties().isEmpty() ? "No parties are being hosted right now." : "No parties match your filters."));
        }
        for (Party p : others)
        {
            list.add(partyCard(p));
        }
        if (showFormed)
        {
            List<FormedParty> formed = new ArrayList<>();
            for (FormedParty f : board.formed())
            {
                if (filter == null || f.getActivity() == filter)
                {
                    formed.add(f);
                }
            }
            list.add(Ui.header("Formed parties (" + formed.size() + ")"));
            if (formed.isEmpty())
            {
                list.add(Ui.empty("No parties have formed in the last 7 days."));
            }
            for (FormedParty f : formed)
            {
                list.add(formedCard(f));
            }
        }
        list.revalidate();
        list.repaint();
        revalidate();
        repaint();
    }

    // ------------------------------------------------------------ cards

    private JPanel partyCard(Party p)
    {
        String rsn = clan.rsn();
        JPanel card = Ui.card();
        boolean hostOnline = board.online().contains(Names.normalize(p.getHostRsn()));
        card.add(titleRow(p.getActivity(), "<b>" + Ui.esc(p.title()) + "</b>" + world(p.getWorld())
            + "  <font color='" + (hostOnline ? "#3FBF3F" : "#BF3F3F") + "'>" + Ui.esc(p.getHostRsn()) + "</font>"));

        StringBuilder meta = new StringBuilder().append(p.memberCount()).append('/').append(p.getCapacity());
        if (p.getLootRule() != LootRule.UNSPECIFIED)
        {
            meta.append(" · ").append(p.getLootRule().getDisplayName());
        }
        if (p.getMinKc() > 0)
        {
            meta.append(" · ").append(p.getMinKc()).append("+ KC");
        }
        if (p.isLearner())
        {
            meta.append(" · Learner");
        }
        if (p.isTeacher())
        {
            meta.append(" · Teacher");
        }
        meta.append(" · ").append(Ui.timeAgo(p.getCreatedAt()));
        card.add(Ui.small(meta.toString(), Ui.MUTED));
        needsLine(card, p);
        if (p.getDescription() != null)
        {
            card.add(Ui.wrapped("\"" + p.getDescription() + "\"", Ui.MUTED));
        }
        List<Applicant> accepted = p.accepted();
        if (!accepted.isEmpty())
        {
            StringBuilder with = new StringBuilder("With: ");
            for (int i = 0; i < accepted.size(); i++)
            {
                with.append(i > 0 ? ", " : "").append(accepted.get(i).getRsn());
            }
            card.add(Ui.wrapped(with.toString(), Ui.MUTED));
        }

        Applicant mine = p.applicantFor(rsn);
        JPanel actions = actionRow();
        if (mine != null)
        {
            String state = mine.isAccepted() ? "Accepted" : mine.isPending() ? "Pending" : "Declined";
            JButton leave = new JButton(mine.isAccepted() ? "Leave party" : mine.isPending() ? "Withdraw" : "Dismiss");
            leave.addActionListener(e -> {
                board.expectSelfLeave(p.getId());
                run(() -> api.withdraw(p.getId(), rsn), "Couldn't withdraw — try again.");
            });
            actions.setLayout(new BorderLayout(5, 0));
            actions.add(Ui.small(state, mine.isAccepted() ? Ui.ONLINE : Ui.MUTED), BorderLayout.CENTER);
            actions.add(leave, BorderLayout.EAST);
            card.add(actions);
        }
        else if (p.getId().equals(applyingId))
        {
            card.add(applyRow(p));
        }
        else
        {
            JButton apply = new JButton("Apply");
            if (rsn == null)
            {
                apply.setEnabled(false);
            }
            else if (board.mine() != null)
            {
                apply.setText("Disband yours to apply");
                apply.setEnabled(false);
            }
            else if (p.isFull())
            {
                apply.setText("Full");
                apply.setEnabled(false);
            }
            else if (p.getActivity().hasRoles() && p.openRoles().isEmpty())
            {
                apply.setText("No open roles");
                apply.setEnabled(false);
            }
            apply.addActionListener(e -> {
                applyingId = p.getId();
                render();
            });
            actions.add(apply);
            card.add(actions);
        }
        return Ui.pinHeight(card);
    }

    private JPanel applicationPanel;
    private String applicationShape;
    private JPanel applyRow(Party p)
    {
        String shape = p.getId() + ":" + p.getActivity() + ":" + p.isHardMode() + ":" + p.openRoles();
        if (shape.equals(applicationShape) && applicationPanel != null) return applicationPanel;
        applicationShape = shape;

        String rsn = clan.rsn();
        JPanel row = Ui.column(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
        JComboBox<Role> roleBox = null;
        if (p.getActivity().hasRoles())
        {
            roleBox = new JComboBox<>(Role.applyOptions(p.getActivity(), p.isHardMode(), p.openRoles()).toArray(new Role[0]));
            row.add(Ui.labeled("Role", roleBox));
        }
        JCheckBox learner = null;
        if (p.getActivity().isRaid())
        {
            learner = Ui.checkbox("I'm a learner");
            row.add(learner);
        }
        // Your KC for this activity: your own client's record first, else
        // a hiscore lookup, else blank to type. Editing it marks the value
        // self-reported. The host sees it; it never blocks applying.
        JSpinner kcSpinner = null;
        Integer prefill = null;
        Party.KcSource source = null;
        if (p.getActivity().hasKillcount())
        {
            prefill = killcounts.local(p.getActivity(), p.isHard());
            if (prefill != null)
            {
                source = Party.KcSource.LOCAL;
            }
            else if (rsn != null && config.lfgKcLookups())
            {
                Killcounts.Hiscore h = killcounts.cached(rsn, p.getActivity());
                if (h == null)
                {
                    killcounts.lookup(rsn, p.getActivity(), () -> SwingUtilities.invokeLater(this::render));
                }
                else if (h.known(p.isHard()))
                {
                    prefill = h.kc(p.isHard());
                    source = Party.KcSource.HISCORES;
                }
            }
            kcSpinner = Ui.spinner(prefill == null ? 0 : prefill, 0, 100_000, 1);
            row.add(Ui.labeled(source == Party.KcSource.LOCAL ? "Your KC (auto)"
                : source == Party.KcSource.HISCORES ? "Your KC (hiscores)" : "Your KC", kcSpinner));
            if (p.getMinKc() > 0)
            {
                boolean below = prefill != null && prefill < p.getMinKc();
                JLabel ask = Ui.note("Host asks for " + p.getMinKc() + "+ KC" + (below ? " - you're below it" : ""));
                if (below)
                {
                    ask.setForeground(ColorScheme.BRAND_ORANGE);
                }
                row.add(ask);
            }
        }
        JPanel buttons = new JPanel(new GridLayout(1, 2, 5, 0));
        buttons.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        buttons.setAlignmentX(LEFT_ALIGNMENT);
        JButton confirm = new JButton("Confirm");
        JButton cancel = new JButton("Cancel");
        JComboBox<Role> roleBoxF = roleBox;
        JCheckBox learnerF = learner;
        JSpinner kcSpinnerF = kcSpinner;
        Integer prefillF = prefill;
        Party.KcSource sourceF = source;
        confirm.addActionListener(e -> {
            if (rsn == null)
            {
                return;
            }
            Role role = roleBoxF == null ? null : (Role) roleBoxF.getSelectedItem();
            boolean isLearner = learnerF != null && learnerF.isSelected();
            Integer kc = null;
            Party.KcSource kcSource = null;
            if (kcSpinnerF != null)
            {
                try { kcSpinnerF.commitEdit(); } catch (java.text.ParseException ex) { showError("Enter a valid kill count."); return; }
                int typed = (Integer) kcSpinnerF.getValue();
                if (prefillF != null && typed == prefillF)
                {
                    kc = typed;
                    kcSource = sourceF;
                }
                else if (typed > 0)
                {
                    kc = typed;
                    kcSource = Party.KcSource.MANUAL;
                }
            }
            Integer kcF = kc;
            Party.KcSource kcSourceF = kcSource;
            board.run(() -> api.apply(p.getId(), rsn, role, isLearner, kcF, kcSourceF), "Couldn't apply. Refresh and try again.",
                message -> SwingUtilities.invokeLater(() -> { if (message == null) applyingId = null; showError(message); render(); }));
        });
        cancel.addActionListener(e -> {
            applyingId = null;
            render();
        });
        buttons.add(confirm);
        buttons.add(cancel);
        row.add(Ui.pinHeight(buttons));
        applicationPanel = Ui.pinHeight(row);
        return applicationPanel;
    }

    private JPanel hostCard(Party p)
    {
        JPanel card = Ui.card();
        card.add(titleRow(p.getActivity(), "<b>" + Ui.esc(p.title()) + "</b>" + world(p.getWorld())
            + "  " + p.memberCount() + "/" + p.getCapacity()));
        needsLine(card, p);
        if (p.getDescription() != null)
        {
            card.add(Ui.wrapped("\"" + p.getDescription() + "\"", Ui.MUTED));
        }
        List<Applicant> pending = p.pending();
        List<Applicant> accepted = p.accepted();
        if (!pending.isEmpty())
        {
            card.add(Ui.small("Applicants (" + pending.size() + ")", ColorScheme.BRAND_ORANGE));
            for (Applicant a : pending)
            {
                card.add(applicantRow(p, a, true));
            }
        }
        if (!accepted.isEmpty())
        {
            card.add(Ui.small("Members", ColorScheme.BRAND_ORANGE));
            for (Applicant a : accepted)
            {
                card.add(applicantRow(p, a, false));
            }
        }
        if (pending.isEmpty() && accepted.isEmpty())
        {
            card.add(Ui.small("No applicants yet.", Ui.MUTED));
        }
        if (!p.isFull())
        {
            card.add(addMemberRow(p));
        }
        JPanel buttons = new JPanel(new GridLayout(1, 2, 5, 0));
        buttons.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        buttons.setAlignmentX(LEFT_ALIGNMENT);
        buttons.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
        JButton edit = new JButton("Edit");
        edit.addActionListener(e -> toggleForm());
        JButton disband = new JButton("Disband");
        disband.addActionListener(e -> {
            board.expectSelfLeave(p.getId());
            run(() -> api.disband(p.getId()), "Couldn't disband — try again.");
        });
        buttons.add(edit);
        buttons.add(disband);
        card.add(Ui.pinHeight(buttons));
        return Ui.pinHeight(card);
    }

    private JPanel applicantRow(Party p, Applicant a, boolean pending)
    {
        JPanel row = Ui.row(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
        boolean online = board.online().contains(Names.normalize(a.getRsn()));
        StringBuilder text = new StringBuilder("<font color='" + (online ? "#3FBF3F" : "#BF3F3F") + "'>")
            .append(Ui.esc(a.getRsn())).append("</font>");
        // Second line: role · learner · KC, kept off the name line so the
        // buttons never clip it.
        List<String> detail = new ArrayList<>();
        if (a.getRole() != null)
        {
            detail.add(Ui.esc(a.getRole().getDisplayName()));
        }
        if (a.isLearner())
        {
            detail.add("learner");
        }
        if (a.isAddedByHost())
        {
            detail.add("added by you");
        }
        else
        {
            String kc = applicantKc(p, a);
            if (kc != null)
            {
                detail.add(kc);
            }
        }
        if (!detail.isEmpty())
        {
            text.append("<br><font color='#A0A0A0'>").append(String.join(" · ", detail)).append("</font>");
        }
        row.add(Ui.html(text.toString()), BorderLayout.CENTER);
        // Pending rows stack Accept over Decline to keep the text column wide.
        JPanel buttons = new JPanel(new GridLayout(pending ? 2 : 1, 1, 0, 2));
        buttons.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        if (pending)
        {
            JButton accept = Ui.smallButton("Accept");
            accept.setEnabled(!p.isFull());
            accept.addActionListener(e -> run(() -> api.setStatus(p.getId(), a.getRsn(), Party.Status.ACCEPTED), "Couldn't accept — try again."));
            JButton decline = Ui.smallButton("Decline");
            decline.addActionListener(e -> run(() -> api.setStatus(p.getId(), a.getRsn(), Party.Status.DECLINED), "Couldn't decline — try again."));
            buttons.add(accept);
            buttons.add(decline);
        }
        else
        {
            JButton kick = Ui.smallButton("Kick");
            kick.addActionListener(e -> run(() -> api.withdraw(p.getId(), a.getRsn()), "Couldn't kick — try again."));
            buttons.add(kick);
        }
        row.add(buttons, BorderLayout.EAST);
        return Ui.pinHeight(row);
    }

    // Seat a buddy who isn't on LFG so the spot shows as taken to everyone.
    private Role addMemberRole;
    private JPanel addMemberRow(Party p)
    {
        JPanel row = Ui.column(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
        row.add(Ui.small("Add a member who isn't on LFG", ColorScheme.BRAND_ORANGE));
        JTextField name = new JTextField(addMemberDraft);
        name.setToolTipText("Their RSN");
        Ui.capLength(name, 12);
        name.getDocument().addDocumentListener(new DocumentListener()
        {
            public void insertUpdate(DocumentEvent e) { addMemberDraft = name.getText(); }
            public void removeUpdate(DocumentEvent e) { addMemberDraft = name.getText(); }
            public void changedUpdate(DocumentEvent e) { addMemberDraft = name.getText(); }
        });
        row.add(Ui.labeled("Name", name));
        JComboBox<Role> roleBox = null;
        if (p.getActivity().hasRoles())
        {
            List<Role> options = new ArrayList<>();
            for (Role r : p.openRoles())
            {
                if (!options.contains(r))
                {
                    options.add(r);
                }
            }
            if (options.isEmpty())
            {
                options = Role.playable(p.getActivity(), p.isHardMode());
            }
            roleBox = new JComboBox<>(options.toArray(new Role[0]));
            if (options.contains(addMemberRole)) roleBox.setSelectedItem(addMemberRole);
            JComboBox<Role> selected = roleBox;
            roleBox.addActionListener(e -> addMemberRole = (Role) selected.getSelectedItem());
            row.add(Ui.labeled("Role", roleBox));
        }
        JComboBox<Role> roleBoxF = roleBox;
        Runnable submit = () -> {
            String rsn = name.getText().trim();
            if (rsn.isEmpty())
            {
                showError("Type their name first.");
                return;
            }
            if (Names.same(rsn, p.getHostRsn()))
            {
                showError("That's you — you're already in.");
                return;
            }
            Role role = roleBoxF == null ? null : (Role) roleBoxF.getSelectedItem();
            board.run(() -> api.addMember(p.getId(), rsn, role) == PartyApi.AddResult.OK,
                "Couldn't add member. Refresh and check the name and available role.", message -> SwingUtilities.invokeLater(() -> {
                    if (message == null) addMemberDraft = "";
                    showError(message);
                }));
        };
        JButton add = new JButton("Add member");
        add.addActionListener(e -> submit.run());
        name.addActionListener(e -> submit.run());
        JPanel buttons = new JPanel(new GridLayout(1, 1));
        buttons.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        buttons.setAlignmentX(LEFT_ALIGNMENT);
        buttons.add(add);
        row.add(Ui.pinHeight(buttons));
        return Ui.pinHeight(row);
    }

    // Read-only record of a party that filled up.
    private JPanel formedCard(FormedParty f)
    {
        String rsn = clan.rsn();
        JPanel card = Ui.card();
        card.add(titleRow(f.getActivity(), "<b>" + Ui.esc(f.title()) + "</b>" + world(f.getWorld())
            + "  " + f.getMembers().size() + "/" + f.getCapacity()));
        card.add(Ui.small("Formed " + Ui.timeAgo(f.getFormedAt()) + " · hosted by " + f.getHostRsn(), Ui.MUTED));
        card.add(Ui.wrapped(f.roster(), f.includes(rsn) ? Color.WHITE : Ui.MUTED));
        if (f.isHostedBy(rsn))
        {
            JPanel actions = actionRow();
            JButton remove = new JButton("Remove");
            remove.setToolTipText("Take this off the formed list now instead of in 7 days");
            remove.addActionListener(e -> run(() -> api.deleteFormed(f.getId()), "Couldn't remove — try again."));
            actions.add(remove);
            card.add(actions);
        }
        return Ui.pinHeight(card);
    }

    // ------------------------------------------------------------ pieces

    // What a host sees next to an applicant, in order of trust: the KC
    // their own client recorded, else a hiscore lookup, else what they
    // typed "(self)", else unknown. Null when the activity has no KC.
    private String applicantKc(Party p, Applicant a)
    {
        if (!p.getActivity().hasKillcount())
        {
            return null;
        }
        if (a.getKc() != null && a.getKcSource() == Party.KcSource.LOCAL)
        {
            return "KC " + a.getKc();
        }
        boolean pending = false;
        if (config.lfgKcLookups())
        {
            Killcounts.Hiscore h = killcounts.cached(a.getRsn(), p.getActivity());
            if (h == null)
            {
                killcounts.lookup(a.getRsn(), p.getActivity(), () -> SwingUtilities.invokeLater(this::render));
                pending = true;
            }
            else if (h.known(p.isHard()))
            {
                return "KC " + h.kc(p.isHard()) + " (hiscores)";
            }
        }
        if (a.getKc() != null)
        {
            return "KC " + a.getKc() + " (self)";
        }
        return pending ? "KC ..." : "KC ?";
    }

    private void needsLine(JPanel card, Party p)
    {
        if (p.getActivity().hasRoles())
        {
            String needs = p.isFull() ? "" : Role.summarize(p.openRoles());
            card.add(Ui.wrapped(p.isFull() ? "Full" : needs.isEmpty() ? "Roles: any" : "Needs: " + needs, Ui.MUTED));
        }
        else if (p.isFull())
        {
            card.add(Ui.small("Full", Ui.MUTED));
        }
    }

    private JPanel titleRow(Activity activity, String html)
    {
        JPanel row = Ui.row(ColorScheme.DARKER_GRAY_COLOR);
        row.add(Ui.icon(items, activity), BorderLayout.WEST);
        row.add(Ui.html(html), BorderLayout.CENTER);
        return Ui.pinHeight(row);
    }

    private static String world(Integer world)
    {
        return world == null ? "" : " <font color='#A0A0A0'>W" + world + "</font>";
    }

    private static JPanel actionRow()
    {
        JPanel actions = new JPanel(new GridLayout(1, 1, 5, 0));
        actions.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        actions.setAlignmentX(LEFT_ALIGNMENT);
        actions.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
        return actions;
    }

    private void run(java.util.function.BooleanSupplier action, String failure)
    {
        board.run(action, failure, this::showError);
    }

    private void showError(String message)
    {
        SwingUtilities.invokeLater(() -> {
            error.setText(message == null ? "" : message);
            error.setVisible(message != null);
        });
    }
}

package com.github.orgonag.fbclan.ui;

import com.github.orgonag.fbclan.core.Clan;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * The sidebar panel: a locked card until verification passes, then the
 * four tabs. One panel for the plugin's lifetime (RuneLite fixes a
 * navigation button's panel at build time), so verification just flips
 * the visible card.
 */
@Singleton
public class Sidebar extends PluginPanel
{
    private static final String LOCKED = "LOCKED";
    private static final String MAIN = "MAIN";

    private final Clan clan;
    private final CardLayout cards = new CardLayout();
    private final JPanel root = new JPanel(cards);
    private final JLabel status = new JLabel();
    private final JButton retry = new JButton("Retry");
    private final CardLayout tabCards = new CardLayout();
    private final JPanel tabs = new JPanel(tabCards);
    private final Map<String, JButton> tabButtons = new LinkedHashMap<>();
    private final Map<String, Runnable> refreshers = new LinkedHashMap<>();
    private String activeTab = "Drop Log";

    @Inject
    public Sidebar(Clan clan, AnnouncementsTab announcements, DropLogTab dropLog, PartiesTab parties, LeaderboardsTab leaderboards)
    {
        super(false);
        this.clan = clan;
        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        // ---- locked card ----
        JPanel locked = new JPanel(new BorderLayout());
        locked.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JPanel center = new JPanel();
        center.setLayout(new BoxLayout(center, BoxLayout.Y_AXIS));
        center.setBackground(ColorScheme.DARK_GRAY_COLOR);
        center.setBorder(BorderFactory.createEmptyBorder(20, 10, 20, 10));
        JLabel title = new JLabel("Final Boss");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(Color.WHITE);
        title.setAlignmentX(CENTER_ALIGNMENT);
        status.setForeground(Ui.MUTED);
        status.setHorizontalAlignment(SwingConstants.CENTER);
        status.setAlignmentX(CENTER_ALIGNMENT);
        retry.setAlignmentX(CENTER_ALIGNMENT);
        retry.addActionListener(e -> clan.verify());
        center.add(title);
        center.add(Box.createRigidArea(new Dimension(0, 15)));
        center.add(status);
        center.add(Box.createRigidArea(new Dimension(0, 10)));
        center.add(retry);
        locked.add(center, BorderLayout.NORTH);

        // ---- main card: two-row tab bar (Announcements on top) ----
        JPanel main = new JPanel(new BorderLayout());
        main.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JPanel bar = new JPanel();
        bar.setLayout(new BoxLayout(bar, BoxLayout.Y_AXIS));
        bar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        JPanel top = new JPanel(new BorderLayout());
        top.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        top.setBorder(BorderFactory.createEmptyBorder(5, 5, 0, 5));
        top.add(tab("Announcements", announcements, announcements::refresh), BorderLayout.CENTER);
        JPanel bottom = new JPanel(new FlowLayout(FlowLayout.CENTER, 5, 5));
        bottom.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        bottom.add(tab("Drop Log", dropLog, dropLog::refresh));
        bottom.add(tab("LFG", parties, parties::refresh));
        // "PBs" not "Leaderboards": a third wide button wraps off the row.
        bottom.add(tab("PBs", leaderboards, leaderboards::refresh));
        bar.add(top);
        bar.add(bottom);
        tabs.setBackground(ColorScheme.DARK_GRAY_COLOR);
        main.add(bar, BorderLayout.NORTH);
        main.add(tabs, BorderLayout.CENTER);

        root.add(locked, LOCKED);
        root.add(main, MAIN);
        add(root, BorderLayout.CENTER);
        show(Clan.Status.VERIFYING);
        select(activeTab);
    }

    private JButton tab(String name, JPanel panel, Runnable refresh)
    {
        JButton b = new JButton(name);
        b.addActionListener(e -> {
            select(name);
            refresh.run();
        });
        tabButtons.put(name, b);
        refreshers.put(name, refresh);
        tabs.add(panel, name);
        return b;
    }

    private void select(String name)
    {
        activeTab = name;
        tabCards.show(tabs, name);
        tabButtons.forEach((n, b) -> b.setBackground(n.equals(name) ? ColorScheme.BRAND_ORANGE : ColorScheme.DARK_GRAY_COLOR));
    }

    public void refreshActiveTab()
    {
        refreshers.get(activeTab).run();
    }

    // EDT.
    public void show(Clan.Status s)
    {
        switch (s)
        {
            case MEMBER:
                cards.show(root, MAIN);
                return;
            case NOT_MEMBER:
                status.setText("<html><center>You're not a member of Final Boss.<br><br>Visit wiseoldman.net/groups/"
                    + Clan.WOM_GROUP_ID + " for more info.</center></html>");
                retry.setVisible(false);
                break;
            case ERROR:
                status.setText("<html><center>Couldn't verify membership — click to retry.</center></html>");
                retry.setVisible(true);
                break;
            default:
                status.setText("<html><center>Verifying clan membership...</center></html>");
                retry.setVisible(false);
                break;
        }
        cards.show(root, LOCKED);
    }
}

package com.github.orgonag.fbclan.ui;

import com.github.orgonag.fbclan.lfg.Activity;
import com.github.orgonag.fbclan.lfg.Killcounts;
import com.github.orgonag.fbclan.lfg.LootRule;
import com.github.orgonag.fbclan.lfg.Party;
import com.github.orgonag.fbclan.lfg.Role;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import javax.swing.JTextField;
import javax.swing.SpinnerNumberModel;
import net.runelite.client.ui.ColorScheme;

/**
 * The host-a-party form. Everything below the activity picker depends
 * on the activity (and size / hard mode), so that part is rebuilt on
 * change; widget values survive the rebuild.
 */
class HostForm extends JPanel
{
    private final Killcounts killcounts;
    private final JComboBox<Activity> activityBox = new JComboBox<>(Activity.values());
    private final JPanel dynamic = Ui.column(ColorScheme.DARKER_GRAY_COLOR);
    private final JCheckBox hardModeBox = Ui.checkbox("Hard mode");
    private final JSpinner invocationSpinner = Ui.spinner(150, 0, Party.MAX_INVOCATION, 5);
    private final JSpinner sizeSpinner = Ui.spinner(5, Party.MIN_CAPACITY, Party.MAX_CAPACITY, 1);
    private final JComboBox<LootRule> lootBox = new JComboBox<>(LootRule.values());
    private final JSpinner minKcSpinner = Ui.spinner(0, 0, 100_000, 10);
    private final JCheckBox learnerBox = Ui.checkbox("Learner");
    private final JCheckBox teacherBox = Ui.checkbox("Teacher");
    private final JComboBox<Role> hostRoleBox = new JComboBox<>();
    private final Map<Role, JSpinner> coxCounts = new EnumMap<>(Role.class);
    private final JTextField descField = new JTextField();
    private final JLabel worldLabel = Ui.note("World: unknown");
    private final JButton submit = new JButton("Create");
    private boolean rebuilding;

    HostForm(Killcounts killcounts, Runnable onSubmit, Runnable onCancel)
    {
        this.killcounts = killcounts;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(ColorScheme.DARKER_GRAY_COLOR);
        setBorder(BorderFactory.createEmptyBorder(5, 5, 5, 5));
        setAlignmentX(LEFT_ALIGNMENT);

        activityBox.setRenderer(new Ui.ActivityRenderer());
        activityBox.setAlignmentX(LEFT_ALIGNMENT);
        activityBox.addActionListener(e -> rebuild());
        add(Ui.pinHeight(activityBox));
        add(Box.createRigidArea(new Dimension(0, 3)));
        add(dynamic);

        sizeSpinner.addChangeListener(e -> rebuild());
        hardModeBox.addActionListener(e -> rebuild());
        learnerBox.addActionListener(e -> {
            if (learnerBox.isSelected()) teacherBox.setSelected(false);
        });
        teacherBox.addActionListener(e -> {
            if (teacherBox.isSelected()) learnerBox.setSelected(false);
        });
        descField.setToolTipText("Optional description (max " + Party.MAX_DESCRIPTION + " chars)");
        Ui.capLength(descField, Party.MAX_DESCRIPTION);
        add(Ui.labeled("Description", descField));
        add(worldLabel);

        JPanel buttons = new JPanel(new GridLayout(1, 2, 5, 0));
        buttons.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        buttons.setAlignmentX(LEFT_ALIGNMENT);
        submit.addActionListener(e -> onSubmit.run());
        JButton cancel = new JButton("Cancel");
        cancel.addActionListener(e -> onCancel.run());
        buttons.add(submit);
        buttons.add(cancel);
        add(Box.createRigidArea(new Dimension(0, 5)));
        add(Ui.pinHeight(buttons));
        rebuild();
    }

    void setEditing(boolean editing)
    {
        submit.setText(editing ? "Save" : "Create");
    }

    void setWorld(int world)
    {
        worldLabel.setText(world > 0 ? "World: " + world + " (your current world)" : "World: unknown");
    }

    // Fill from an existing party (Edit).
    void populate(Party p)
    {
        activityBox.setSelectedItem(p.getActivity());
        hardModeBox.setSelected(p.isHardMode());
        invocationSpinner.setValue(p.getInvocation());
        rebuild();
        SpinnerNumberModel m = (SpinnerNumberModel) sizeSpinner.getModel();
        sizeSpinner.setValue(Ui.clamp(p.getCapacity(), (Integer) m.getMinimum(), (Integer) m.getMaximum()));
        lootBox.setSelectedItem(p.getLootRule());
        minKcSpinner.setValue(p.getMinKc());
        learnerBox.setSelected(p.isLearner());
        teacherBox.setSelected(p.isTeacher());
        descField.setText(p.getDescription() == null ? "" : p.getDescription());
        rebuild();
        if (p.getHostRole() != null)
        {
            hostRoleBox.setSelectedItem(p.getHostRole());
        }
        if (p.getActivity() == Activity.COX)
        {
            coxCounts.values().forEach(s -> s.setValue(0));
            for (Role r : p.getRequiredRoles())
            {
                JSpinner s = coxCounts.get(r);
                if (s != null)
                {
                    s.setValue((Integer) s.getValue() + 1);
                }
            }
        }
    }

    // The party the form describes; id/created_at are server-owned.
    Party build(String hostRsn, int world)
    {
        try
        {
            sizeSpinner.commitEdit(); invocationSpinner.commitEdit(); minKcSpinner.commitEdit();
            for (JSpinner spinner : coxCounts.values()) spinner.commitEdit();
        }
        catch (java.text.ParseException e) { throw new IllegalArgumentException("Enter valid numeric values."); }
        Activity activity = (Activity) activityBox.getSelectedItem();
        boolean hard = activity.hasHardMode() && hardModeBox.isSelected();
        int capacity = (Integer) sizeSpinner.getValue();
        Map<Role, Integer> counts = new EnumMap<>(Role.class);
        coxCounts.forEach((r, s) -> counts.put(r, (Integer) s.getValue()));
        return Party.builder()
            .hostRsn(hostRsn)
            .activity(activity)
            .hardMode(hard)
            .invocation(activity.usesInvocation() ? (Integer) invocationSpinner.getValue() : 0)
            .capacity(capacity)
            .description(descField.getText())
            .world(world > 0 ? world : null)
            .minKc(activity.hasKillcount() ? (Integer) minKcSpinner.getValue() : 0)
            .lootRule((LootRule) lootBox.getSelectedItem())
            .requiredRoles(Role.required(activity, hard, capacity, counts))
            .hostRole(activity.hasRoles() ? (Role) hostRoleBox.getSelectedItem() : null)
            .learner(activity.isRaid() && learnerBox.isSelected())
            .teacher(activity.isRaid() && teacherBox.isSelected())
            .createdAt(Instant.now())
            .applicants(Collections.emptyList())
            .build();
    }

    // Listeners on the widgets adjusted here call back in; the guard stops
    // the nested call from re-adding rows mid-rebuild.
    private void rebuild()
    {
        if (rebuilding)
        {
            return;
        }
        rebuilding = true;
        try
        {
            rebuildInner();
        }
        finally
        {
            rebuilding = false;
        }
    }

    private void rebuildInner()
    {
        Activity activity = (Activity) activityBox.getSelectedItem();
        dynamic.removeAll();

        if (activity.hasHardMode())
        {
            hardModeBox.setText(activity == Activity.TOB ? "Hard mode (HMT)"
                : activity == Activity.COX ? "Challenge mode (CM)" : activity.getHardModeLabel());
            dynamic.add(hardModeBox);
        }
        else
        {
            hardModeBox.setSelected(false);
        }
        if (activity.usesInvocation())
        {
            dynamic.add(Ui.labeled("Invocation", invocationSpinner));
        }

        int min = Math.max(Party.MIN_CAPACITY, activity.getMinPartySize());
        int max = Math.max(min, activity.getMaxPartySize());
        SpinnerNumberModel sizeModel = (SpinnerNumberModel) sizeSpinner.getModel();
        int size = Ui.clamp((Integer) sizeSpinner.getValue(), min, max);
        sizeModel.setMinimum(min);
        sizeModel.setMaximum(max);
        if ((Integer) sizeSpinner.getValue() != size)
        {
            sizeSpinner.setValue(size);
        }
        dynamic.add(Ui.labeled("Party size", sizeSpinner));
        dynamic.add(Ui.labeled("Loot", lootBox));
        if (activity.hasKillcount())
        {
            dynamic.add(Ui.labeled("Min KC (0=any)", minKcSpinner));
            Integer mine = killcounts.local(activity, activity.hasHardMode() && hardModeBox.isSelected());
            if (mine != null)
            {
                dynamic.add(Ui.note("Your KC: " + mine));
            }
        }
        else
        {
            minKcSpinner.setValue(0);
        }

        if (activity.isRaid())
        {
            JPanel tags = new JPanel(new GridLayout(1, 2));
            tags.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            tags.setAlignmentX(LEFT_ALIGNMENT);
            tags.add(learnerBox);
            tags.add(teacherBox);
            dynamic.add(Ui.pinHeight(tags));
        }
        else
        {
            learnerBox.setSelected(false);
            teacherBox.setSelected(false);
        }

        if (activity.hasRoles())
        {
            boolean hard = hardModeBox.isSelected();
            // Read the pick before clearing, so a size/mode change keeps it.
            Role previous = (Role) hostRoleBox.getSelectedItem();
            hostRoleBox.removeAllItems();
            List<Role> roles = activity == Activity.TOB ? distinct(Role.tobComposition(size, hard)) : Role.playable(activity, hard);
            roles.forEach(hostRoleBox::addItem);
            if (previous != null && roles.contains(previous))
            {
                hostRoleBox.setSelectedItem(previous);
            }
            dynamic.add(Ui.labeled("Your role", hostRoleBox));
            if (activity == Activity.TOB)
            {
                dynamic.add(Ui.wrapped("Team: " + Role.summarize(Role.tobComposition(size, hard)), Ui.MUTED));
            }
            else if (activity == Activity.COX)
            {
                dynamic.add(Ui.note("Roles wanted (rest = Fill):"));
                Map<Role, Integer> keep = new EnumMap<>(Role.class);
                coxCounts.forEach((r, s) -> keep.put(r, (Integer) s.getValue()));
                coxCounts.clear();
                for (Role r : Role.playable(activity, hard))
                {
                    if (!r.isFill())
                    {
                        JSpinner s = Ui.spinner(keep.getOrDefault(r, 0), 0, max, 1);
                        coxCounts.put(r, s);
                        dynamic.add(Ui.labeled("  " + r.getDisplayName(), s));
                    }
                }
            }
            else
            {
                dynamic.add(Ui.note("One of each role; a 5th may double up."));
            }
        }
        else
        {
            hostRoleBox.removeAllItems();
        }
        dynamic.revalidate();
        dynamic.repaint();
        revalidate();
    }

    private static List<Role> distinct(List<Role> roles)
    {
        List<Role> out = new ArrayList<>();
        for (Role r : roles)
        {
            if (!out.contains(r))
            {
                out.add(r);
            }
        }
        return out;
    }
}

package com.github.orgonag.fbclan.ui;

import com.github.orgonag.fbclan.core.Supabase;
import com.github.orgonag.fbclan.drops.DropLogger;
import com.github.orgonag.fbclan.drops.DropRules;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.LinkBrowser;

/** The last 50 clan drops. */
@Singleton
public class DropLogTab extends JPanel
{
    private final DropLogger drops;
    private final ScheduledExecutorService executor;
    private final JPanel list;
    private final javax.swing.JTextArea refreshError = Ui.plain("");
    private final java.util.concurrent.atomic.AtomicBoolean refreshing = new java.util.concurrent.atomic.AtomicBoolean();

    @Inject
    public DropLogTab(DropLogger drops, ScheduledExecutorService executor)
    {
        this.drops = drops;
        this.executor = executor;
        setLayout(new BorderLayout());
        add(refreshError, BorderLayout.NORTH);
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        list = Ui.scrollList(this);
    }

    public void refresh()
    {
        if (!refreshing.compareAndSet(false, true)) return;
        Ui.async(executor, () -> drops.recent(50), rows -> { refreshing.set(false); render(rows); }, message -> { if (message != null) refreshing.set(false); refreshError.setText(message == null ? "" : message); });
    }

    private void render(JsonArray rows)
    {
        list.removeAll();
        if (rows.size() == 0)
        {
            list.add(Ui.empty("No drops logged yet."));
        }
        for (JsonElement el : rows)
        {
            list.add(row(el.getAsJsonObject()));
        }
        list.revalidate();
        list.repaint();
    }

    private JPanel row(JsonObject drop)
    {
        JPanel row = Ui.row(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
            BorderFactory.createEmptyBorder(3, 8, 3, 8)));
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 38));

        long value = Supabase.longOr(drop, "ge_value", 0);
        String suffix = value > 0 ? " (" + DropRules.formatGp(value) + " GP)" : "";
        if (Supabase.has(drop, "rarity") && Supabase.doubleOr(drop,"rarity",0) > 0)
        {
            suffix += " [" + DropRules.formatRarity(Supabase.doubleOr(drop,"rarity",0)) + "]";
        }
        // Plain labels truncate with "..." where HTML would wrap and grow.
        JLabel main = new JLabel(Supabase.str(drop, "item_name") + suffix);
        main.putClientProperty("html.disable", Boolean.TRUE);
        main.setToolTipText(main.getText());
        main.setForeground(Color.WHITE);
        main.setFont(FontManager.getRunescapeSmallFont().deriveFont(Font.BOLD));
        JLabel detail = Ui.small(Supabase.str(drop, "rsn") + " — " + Supabase.str(drop, "npc_name")
            + " — " + Ui.timeAgo(Supabase.str(drop, "created_at")), Ui.MUTED);
        JPanel stack = Ui.column(ColorScheme.DARKER_GRAY_COLOR);
        stack.add(main);
        stack.add(detail);
        row.add(stack, BorderLayout.CENTER);

        // The drops table is anon-writable, so a screenshot link is only
        // honoured when it points into the plugin's own public bucket.
        String url = Supabase.str(drop, "screenshot_url");
        if (url.startsWith(DropLogger.screenshotPrefix()))
        {
            JLabel pic = Ui.small("[pic]", ColorScheme.BRAND_ORANGE);
            pic.setToolTipText("Click to view screenshot");
            row.add(pic, BorderLayout.EAST);
            row.setToolTipText("Click to view screenshot");
            row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            row.addMouseListener(new MouseAdapter()
            {
                @Override
                public void mousePressed(MouseEvent e)
                {
                    LinkBrowser.browse(url);
                }
            });
        }
        return row;
    }
}

package com.github.orgonag.fbclan.ui;

import com.github.orgonag.fbclan.lfg.Activity;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.time.Duration;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import java.util.function.Supplier;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.DefaultListCellRenderer;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JSpinner;
