/**
 * Shared Swing helpers for the sidebar. Two rules keep BoxLayout honest:
 * every child uses LEFT_ALIGNMENT (mixed alignments shift siblings
 * sideways), and a child's max height is pinned to its preferred height
 * from the look-and-feel, never hard-coded smaller.
 */
public final class Ui
{
    public static final Color ONLINE = new Color(0x3F, 0xBF, 0x3F);
    public static final Color MUTED = ColorScheme.LIGHT_GRAY_COLOR;
    public static final Color GOLD = new Color(0xffd700);
    public static final int ICON = 20;
    // Card inner width: sidebar (242) minus the card's 8px side padding.
    private static final int WRAP_WIDTH = 226;
    private static final ImageIcon PLACEHOLDER = new ImageIcon(new BufferedImage(ICON, ICON, BufferedImage.TYPE_INT_ARGB));

    private Ui()
    {
    }

    // Fetch on the executor, apply on the EDT. Never block the EDT on network.
    public static <T> void async(ScheduledExecutorService executor, Supplier<T> fetch, Consumer<T> applyOnEdt)
    {
        async(executor, fetch, applyOnEdt, message -> {});
    }

    public static <T> void async(ScheduledExecutorService executor, Supplier<T> fetch, Consumer<T> applyOnEdt,
                                Consumer<String> errorOnEdt)
    {
        executor.submit(() -> {
            try
            {
                T result = fetch.get();
                SwingUtilities.invokeLater(() -> { errorOnEdt.accept(null); applyOnEdt.accept(result); });
            }
            catch (RuntimeException e)
            {
                SwingUtilities.invokeLater(() -> errorOnEdt.accept("Refresh failed. Previous data may be out of date."));
            }
        });
    }

    // ------------------------------------------------------------ containers

    // A vertical list inside a scroll pane that tracks the viewport width.
    public static JPanel scrollList(JPanel host)
    {
        JPanel list = new ScrollList();
        list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
        list.setBackground(ColorScheme.DARK_GRAY_COLOR);
        JScrollPane scroll = new JScrollPane(list);
        scroll.setBackground(ColorScheme.DARK_GRAY_COLOR);
        scroll.getViewport().setBackground(ColorScheme.DARK_GRAY_COLOR);
        scroll.setBorder(null);
        scroll.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        host.add(scroll, BorderLayout.CENTER);
        return list;
    }

    public static JPanel card()
    {
        JPanel card = new JPanel();
        card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
        card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        card.setAlignmentX(Component.LEFT_ALIGNMENT);
        card.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
            BorderFactory.createEmptyBorder(5, 8, 6, 8)));
        return card;
    }

    public static JPanel row(Color bg)
    {
        JPanel row = new JPanel(new BorderLayout(5, 0));
        row.setBackground(bg);
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        return row;
    }

    public static JPanel column(Color bg)
    {
        JPanel col = new JPanel();
        col.setLayout(new BoxLayout(col, BoxLayout.Y_AXIS));
        col.setBackground(bg);
        col.setAlignmentX(Component.LEFT_ALIGNMENT);
        return col;
    }

    public static <T extends JComponent> T pinHeight(T c)
    {
        c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
        return c;
    }

    // ------------------------------------------------------------ text

    public static JLabel html(String inner)
    {
        JLabel l = new JLabel("<html>" + inner + "</html>");
        l.setForeground(Color.WHITE);
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setAlignmentX(Component.LEFT_ALIGNMENT);
        return l;
    }

    public static JLabel small(String text, Color color)
    {
        JLabel l = new JLabel(text);
        l.putClientProperty("html.disable", Boolean.TRUE);
        l.setForeground(color);
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setAlignmentX(Component.LEFT_ALIGNMENT);
        return l;
    }

    public static JLabel note(String text)
    {
        JLabel l = small(text, MUTED);
        l.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
        return l;
    }

    public static JLabel header(String text)
    {
        JLabel h = new JLabel(" " + text);
        h.setFont(FontManager.getRunescapeBoldFont());
        h.setForeground(ColorScheme.BRAND_ORANGE);
        h.setAlignmentX(Component.LEFT_ALIGNMENT);
        h.setBorder(BorderFactory.createEmptyBorder(8, 0, 4, 0));
        return pinHeight(h);
    }

    public static JLabel empty(String text)
    {
        JLabel l = new JLabel(text);
        l.putClientProperty("html.disable", Boolean.TRUE);
        l.setForeground(MUTED);
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setHorizontalAlignment(SwingConstants.CENTER);
        l.setAlignmentX(Component.LEFT_ALIGNMENT);
        l.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
        l.setBorder(BorderFactory.createEmptyBorder(6, 0, 6, 0));
        return l;
    }

    // Multi-line text wrapped to the sidebar width. A JTextArea, not an
    // HTML label: Swing's HTML layout under-measures the RuneScape font
    // and clips wrapped lines. Pre-sizing to the wrap width makes the
    // preferred height reflect the wrapped line count.
    public static JTextArea wrapped(String text, Color color)
    {
        JTextArea t = new JTextArea(text);
        t.setLineWrap(true);
        t.setWrapStyleWord(true);
        t.setEditable(false);
        t.setFocusable(false);
        t.setHighlighter(null);
        t.setOpaque(false);
        t.setForeground(color);
        t.setFont(FontManager.getRunescapeSmallFont());
        t.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));
        t.setAlignmentX(Component.LEFT_ALIGNMENT);
        t.setSize(new Dimension(WRAP_WIDTH, Short.MAX_VALUE));
        t.setMaximumSize(new Dimension(Integer.MAX_VALUE, t.getPreferredSize().height));
        return t;
    }

    // Plain (non-HTML) text area for remote content: nothing to inject.
    public static JTextArea plain(String text)
    {
        JTextArea area = new JTextArea(text);
        area.setEditable(false);
        area.setFocusable(false);
        area.setLineWrap(true);
        area.setWrapStyleWord(true);
        area.setOpaque(false);
        area.setForeground(MUTED);
        area.setFont(FontManager.getRunescapeFont());
        area.setBorder(null);
        area.setAlignmentX(Component.LEFT_ALIGNMENT);
        area.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
        return area;
    }

    public static String esc(String s)
    {
        return s == null ? "" : s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
    }

    public static String timeAgo(Instant then)
    {
        long minutes = Duration.between(then, Instant.now()).toMinutes();
        if (minutes < 1)
        {
            return "just now";
        }
        if (minutes < 60)
        {
            return minutes + " min ago";
        }
        if (minutes < 60 * 24)
        {
            return (minutes / 60) + "h ago";
        }
        return (minutes / (60 * 24)) + "d ago";
    }

    public static String timeAgo(String iso)
    {
        try
        {
            return timeAgo(OffsetDateTime.parse(iso).toInstant());
        }
        catch (RuntimeException e)
        {
            return "";
        }
    }

    // ------------------------------------------------------------ inputs

    public static JPanel labeled(String label, JComponent field)
    {
        JPanel row = row(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
        JLabel l = new JLabel(label);
        l.setFont(FontManager.getRunescapeSmallFont());
        l.setForeground(MUTED);
        l.setPreferredSize(new Dimension(80, 22));
        row.add(l, BorderLayout.WEST);
        row.add(field, BorderLayout.CENTER);
        return pinHeight(row);
    }

    public static JCheckBox checkbox(String text)
    {
        JCheckBox box = new JCheckBox(text);
        box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        box.setForeground(Color.WHITE);
        box.setFont(FontManager.getRunescapeSmallFont());
        box.setAlignmentX(Component.LEFT_ALIGNMENT);
        return box;
    }

    public static JSpinner spinner(int value, int min, int max, int step)
    {
        return new JSpinner(new SpinnerNumberModel(clamp(value, min, max), min, max, step));
    }

    public static JButton smallButton(String text)
    {
        JButton b = new JButton(text);
        b.setFont(FontManager.getRunescapeSmallFont());
        b.setMargin(new java.awt.Insets(1, 4, 1, 4));
        return b;
    }

    public static int clamp(int v, int min, int max)
    {
        return Math.max(min, Math.min(max, v));
    }

    public static void capLength(JTextField field, int max)
    {
        ((AbstractDocument) field.getDocument()).setDocumentFilter(new DocumentFilter()
        {
            @Override
            public void insertString(FilterBypass fb, int offset, String string, AttributeSet attr) throws BadLocationException
            {
                if (string != null && fb.getDocument().getLength() + string.length() <= max)
                {
                    super.insertString(fb, offset, string, attr);
                }
            }

            @Override
            public void replace(FilterBypass fb, int offset, int length, String text, AttributeSet attrs) throws BadLocationException
            {
                int newLength = fb.getDocument().getLength() - length + (text == null ? 0 : text.length());
                if (newLength <= max)
                {
                    super.replace(fb, offset, length, text, attrs);
                }
            }
        });
    }

    // ------------------------------------------------------------ activities

    // "Category: Name" so the long dropdown scans; other values pass through.
    public static final class ActivityRenderer extends DefaultListCellRenderer
    {
        @Override
        public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean selected, boolean focus)
        {
            Object display = value;
            if (value instanceof Activity)
            {
                Activity a = (Activity) value;
                display = a.getCategory() == Activity.Category.GENERAL
                    ? a.getDisplayName() : a.getCategory().getDisplayName() + ": " + a.getDisplayName();
            }
            return super.getListCellRendererComponent(list, display, index, selected, focus);
        }
    }

    // The activity's item sprite from RuneLite's item cache, once loaded
    // (placeholder first so the row never reflows).
    public static JLabel icon(ItemManager items, Activity activity)
    {
        JLabel label = new JLabel(PLACEHOLDER);
        label.setPreferredSize(new Dimension(ICON, ICON));
        label.setToolTipText(activity.getDisplayName());
        AsyncBufferedImage sprite = items.getImage(activity.getIconItemId());
        sprite.onLoaded(() -> SwingUtilities.invokeLater(() -> {
            label.setIcon(new ImageIcon(ImageUtil.resizeImage(sprite, ICON, ICON)));
            label.repaint();
        }));
        return label;
    }

    // JPanel isn't Scrollable: inside a scroll pane it takes its preferred
    // width and long lines overflow. Tracking the viewport width makes
    // wrapped children wrap to the real panel width.
    private static class ScrollList extends JPanel implements Scrollable
    {
        @Override
        public Dimension getPreferredScrollableViewportSize()
        {
            return getPreferredSize();
        }

        @Override
        public int getScrollableUnitIncrement(Rectangle r, int o, int d)
        {
            return 16;
        }

        @Override
        public int getScrollableBlockIncrement(Rectangle r, int o, int d)
        {
            return 64;
        }

        @Override
        public boolean getScrollableTracksViewportWidth()
        {
            return true;
        }

        @Override
        public boolean getScrollableTracksViewportHeight()
        {
            return false;
        }
    }
}

package com.github.orgonag.fbclan.clan;

import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.core.Names;
import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;

/**
 * Clan-curated, read-only content: announcements, the once-per-session
 * welcome message, and the notable-items list. All three live in
 * Supabase tables written solely by the clan's sheet-sync script; the
 * plugin only reads them. Fetches run on the executor and fail soft,
 * keeping the previous value.
 */
@Singleton
public class ClanContent
{
    @Value
    public static class Announcement
    {
        String date;  // YYYY-MM-DD, may be blank
        String title;
        String body;  // newlines preserved
    }

    private static final int MAX_TITLE = 200;
    private static final int MAX_BODY = 10_000;
    private static final int MAX_WELCOME = 200;
    private static final String WELCOME_COLOR = "a020f0";

    private final Supabase db;
    private final Clan clan;
    private final Client client;
    private final ClientThread clientThread;

    private volatile List<Announcement> announcements = Collections.emptyList();
    private volatile Set<String> notableItems = Collections.emptySet();
    private volatile String welcome = "";
    private volatile boolean welcomeShown;

    @Inject
    public ClanContent(Supabase db, Clan clan, Client client, ClientThread clientThread)
    {
        this.db = db;
        this.clan = clan;
        this.client = client;
        this.clientThread = clientThread;
    }

    public List<Announcement> announcements()
    {
        return announcements;
    }

    // Normalized item-name keys (see Names.itemKey).
    public Set<String> notableItems()
    {
        return notableItems;
    }

    public void resetSession()
    {
        welcomeShown = false;
    }

    // ------------------------------------------------------------ fetches

    // Fetch failures keep the previous value; an empty table clears it.
    public boolean refreshAnnouncements()
    {
        JsonArray rows = db.getOrNull("announcements", "select=posted_at,title,body&order=posted_at.desc,sort_order.asc");
        if (rows == null)
        {
            return false;
        }
        List<Announcement> out = new ArrayList<>();
        for (JsonElement el : rows)
        {
            JsonObject row = el.getAsJsonObject();
            String title = cap(Supabase.str(row, "title"), MAX_TITLE);
            String body = cap(Supabase.str(row, "body"), MAX_BODY);
            if (!title.isEmpty() || !body.isEmpty())
            {
                out.add(new Announcement(Supabase.str(row, "posted_at"), title, body));
            }
        }
        announcements = Collections.unmodifiableList(out);
        return true;
    }

    // Once per session: the list changes rarely.
    public void refreshNotableItems()
    {
        JsonArray rows = db.getOrNull("notable_items", "select=name");
        if (rows == null)
        {
            return;
        }
        Set<String> names = new HashSet<>();
        for (JsonElement el : rows)
        {
            String key = Names.itemKey(Supabase.str(el.getAsJsonObject(), "name"));
            if (!key.isEmpty())
            {
                names.add(key);
            }
        }
        notableItems = Collections.unmodifiableSet(names);
    }

    public void refreshWelcome()
    {
        JsonArray rows = db.getOrNull("welcome_message", "select=message&id=eq.1");
        if (rows == null)
        {
            return;
        }
        // Remote text printed into the chatbox: strip anything that could
        // read as chat markup, collapse whitespace, cap the length.
        String raw = rows.size() == 0 ? "" : Supabase.str(rows.get(0).getAsJsonObject(), "message");
        String clean = raw.replaceAll("<[^>]*>", "").replace("<", "").replace(">", "")
            .replaceAll("\\s+", " ").trim();
        welcome = cap(clean, MAX_WELCOME);
    }

    // ------------------------------------------------------------ welcome

    // Called after the startup fetch and after verification; whichever
    // lands last prints the line. Synchronized: both callers are executor
    // threads.
    public synchronized void maybeShowWelcome()
    {
        com.github.orgonag.fbclan.core.Session session = clan.snapshot();
        String message = welcome;
        if (!clan.isVerified() || welcomeShown || message.isEmpty())
        {
            return;
        }
        welcomeShown = true;
        clientThread.invokeLater(() -> {
            if (!clan.current(session)) return true;
            GameState gs = client.getGameState();
            if (gs == GameState.LOADING || gs == GameState.HOPPING || gs == GameState.CONNECTION_LOST)
            {
                return false; // transient — try again next tick
            }
            if (!clan.isVerified() || gs != GameState.LOGGED_IN)
            {
                welcomeShown = false; // true logout — re-attempt next login
                return true;
            }
            // postEvent=false keeps our own line out of the chat-event
            // pipeline (the pet matcher would otherwise see it).
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                "<col=" + WELCOME_COLOR + ">[Final Boss] " + message + "</col>", null, false);
            return true;
        });
    }

    private static String cap(String s, int max)
    {
        return s.length() > max ? s.substring(0, max) : s;
    }
}

package com.github.orgonag.fbclan;

import com.github.orgonag.fbclan.drops.DropRules;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

// Key names are stable across versions so members' settings survive.
@ConfigGroup("finalboss")
public interface FinalBossConfig extends Config
{
    @ConfigSection(name = "Drop Logging", description = "Settings for drop logging", position = 0)
    String dropLoggingSection = "dropLogging";

    @ConfigSection(name = "Looking For Group", description = "Settings for the LFG party board", position = 1)
    String lfgSection = "lfg";

    @ConfigSection(name = "Discord Integration", description = "Settings for Discord webhook", position = 2)
    String discordSection = "discord";

    @ConfigSection(name = "Leaderboards", description = "Clan leaderboards settings", position = 3)
    String leaderboardsSection = "leaderboards";

    // ------------------------------------------------------------ drops

    @ConfigItem(
        keyName = "enableDropLogging",
        name = "Enable Drop Logging",
        description = "Log valuable drops to the clan database. On by default for verified clan members — disable to opt out.",
        section = dropLoggingSection,
        position = 0
    )
    default boolean enableDropLogging()
    {
        return true;
    }

    @Range(min = DropRules.MIN_THRESHOLD_GP)
    @ConfigItem(
        keyName = "dropThresholdGp",
        name = "Valuable drop threshold (GP)",
        description = "Any drop worth at least this much (GE price x quantity) is logged, rare or not — 1m minimum",
        section = dropLoggingSection,
        position = 1
    )
    default int dropThresholdGp()
    {
        return DropRules.MIN_THRESHOLD_GP;
    }

    @Range(min = 0, max = 1_000_000)
    @ConfigItem(
        keyName = "rareDropThreshold",
        name = "Rare drop threshold (1 in X)",
        description = "Log drops whose drop rate is 1 in X or rarer, even below the valuable threshold. "
            + "100 = 1% or rarer. 0 turns the rarity rule off. Uses the OSRS Wiki drop table; "
            + "drops it doesn't cover only qualify by value or the clan's notable list.",
        section = dropLoggingSection,
        position = 2
    )
    default int rareDropThreshold()
    {
        return 100;
    }

    @Range(min = 0)
    @ConfigItem(
        keyName = "rareDropMinValueGp",
        name = "Rare drop min value (GP)",
        description = "A rare drop must also be worth at least this much to be logged, so 1/128 rune junk "
            + "stays out. Set to 0 to log every rare drop regardless of value (untradeables included).",
        section = dropLoggingSection,
        position = 3
    )
    default int rareDropMinValueGp()
    {
        return 100_000;
    }

    @ConfigItem(
        keyName = "enableDropScreenshots",
        name = "Screenshot Drops",
        description = "Capture a full client screenshot for drops above the threshold and store it in the clan database",
        section = dropLoggingSection,
        position = 4
    )
    default boolean enableDropScreenshots()
    {
        return false;
    }

    // ------------------------------------------------------------ lfg

    @ConfigItem(
        keyName = "enableLfg",
        name = "Enable LFG",
        description = "Enable the Looking For Group party board and the !lfg chat command",
        section = lfgSection,
        position = 0
    )
    default boolean enableLfg()
    {
        return true;
    }

    @ConfigItem(
        keyName = "lfgPartyNotifications",
        name = "Party chat notifications",
        description = "Post LFG party events to your chatbox: applicants to your party, "
            + "your application being accepted or declined, and parties you're in forming or being disbanded",
        section = lfgSection,
        position = 1
    )
    default boolean lfgPartyNotifications()
    {
        return true;
    }

    @ConfigItem(
        keyName = "lfgDesktopNotifications",
        name = "Party desktop notifications",
        description = "Also send a desktop notification for LFG party events (uses RuneLite's notification settings)",
        section = lfgSection,
        position = 2
    )
    default boolean lfgDesktopNotifications()
    {
        return false;
    }

    @ConfigItem(
        keyName = "lfgKcLookups",
        name = "Kill count lookups",
        description = "Look up kill counts on the public OSRS hiscores when an applicant's client didn't "
            + "send one, and to prefill your own on the apply form",
        section = lfgSection,
        position = 3
    )
    default boolean lfgKcLookups()
    {
        return true;
    }

    // ------------------------------------------------------------ discord

    @ConfigItem(
        keyName = "discordWebhookUrl",
        name = "Discord Webhook URL",
        description = "Discord webhook URL for drop notifications (leave empty to disable)",
        section = discordSection,
        position = 0
    )
    default String discordWebhookUrl()
    {
        return "";
    }

    // ------------------------------------------------------------ leaderboards

    @ConfigItem(
        keyName = "enablePbUpload",
        name = "Upload personal bests",
        description = "Send your boss personal-best times (RSN, boss name, time) to the clan's leaderboard database. "
            + "On by default — disable to opt out. Skipped on Leagues/Deadman/speedrun worlds.",
        section = leaderboardsSection,
        position = 0
    )
