package com.github.orgonag.fbclan.lfg;

import com.github.orgonag.fbclan.core.Names;
import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import lombok.Value;

/**
 * A party that filled up: a self-contained snapshot (one
 * lfg_formed_parties row) with no links to the live tables, which are
 * deleted when it's written. Kept server-side for 7 days as history.
 */
@Value
public class FormedParty
{
    @Value
    public static class Member
    {
        String rsn;
        Role role;
        boolean addedByHost;
    }

    String id;
    String partyId;   // the live party it came from
    String hostRsn;
    Activity activity;
    boolean hardMode;
    int invocation;
    int capacity;
    Integer world;
    List<Member> members;  // host first
    Instant formedAt;

    public String title()
    {
        return activity.partyTitle(hardMode, invocation);
    }

    public boolean isHostedBy(String rsn)
    {
        return rsn != null && Names.same(hostRsn, rsn);
    }

    public boolean includes(String rsn)
    {
        return rsn != null && members.stream().anyMatch(m -> Names.same(m.getRsn(), rsn));
    }

    // "Shok (Melee), Bud (Ranged), Pal"
    public String roster()
    {
        StringBuilder sb = new StringBuilder();
        for (Member m : members)
        {
            sb.append(sb.length() > 0 ? ", " : "").append(m.getRsn());
            if (m.getRole() != null)
            {
                sb.append(" (").append(m.getRole().getDisplayName()).append(')');
            }
        }
        return sb.toString();
    }

    public static FormedParty from(Party p)
    {
        List<Member> members = new ArrayList<>();
        members.add(new Member(p.getHostRsn(), p.getHostRole(), false));
        for (Party.Applicant a : p.accepted())
        {
            members.add(new Member(a.getRsn(), a.getRole(), a.isAddedByHost()));
        }
        return new FormedParty(null, p.getId(), p.getHostRsn(), p.getActivity(), p.isHardMode(), p.getInvocation(),
            p.getCapacity(), p.getWorld(), members, Instant.now());
    }

    public JsonObject toJson()
    {
        JsonObject d = new JsonObject();
        Supabase.put(d, "party_id", partyId);
        d.addProperty("host_rsn", hostRsn);
        d.addProperty("activity", activity.key());
        d.addProperty("hard_mode", hardMode);
        d.addProperty("invocation", invocation);
        d.addProperty("capacity", capacity);
        Supabase.put(d, "world", world);
        JsonArray arr = new JsonArray();
        for (Member m : members)
        {
            JsonObject o = new JsonObject();
            o.addProperty("rsn", m.getRsn());
            Supabase.put(o, "role", m.getRole() == null ? null : m.getRole().key());
            o.addProperty("added_by_host", m.isAddedByHost());
            arr.add(o);
        }
        d.add("members", arr);
        return d;
    }

    public static FormedParty fromRow(JsonObject row)
    {
        Activity activity = Activity.fromKey(Supabase.str(row, "activity"));
        if (activity == null || Supabase.str(row, "id").isEmpty() || Supabase.str(row, "host_rsn").isEmpty())
        {
            return null;
        }
        List<Member> members = new ArrayList<>();
        if (Supabase.has(row, "members") && row.get("members").isJsonArray())
        {
            for (JsonElement el : row.getAsJsonArray("members"))
            {
                if (!el.isJsonObject())
                {
                    continue;
                }
                JsonObject o = el.getAsJsonObject();
                String rsn = Supabase.str(o, "rsn");
                if (!rsn.isEmpty())
                {
                    members.add(new Member(rsn, Role.fromKey(Supabase.str(o, "role")), Supabase.bool(o, "added_by_host")));
                }
            }
        }
        return new FormedParty(Supabase.str(row, "id"),
            Supabase.has(row, "party_id") ? Supabase.str(row, "party_id") : null,
            Supabase.str(row, "host_rsn"), activity, Supabase.bool(row, "hard_mode"),
            Supabase.intOr(row, "invocation", 0), Supabase.intOr(row, "capacity", Math.max(1, members.size())),
            Supabase.intOrNull(row, "world"), members, Supabase.instant(row, "formed_at", Instant.now()));
    }
}

package com.github.orgonag.fbclan.lfg;

import com.github.orgonag.fbclan.core.ApiResult;
import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.core.Session;
import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;

/** Version 3 transactional API. Each logical write has one retry identity. */
@Singleton
public class PartyApi
{
    public enum AddResult { OK, REJECTED, FAILED }
    @Value public static class Snapshot { List<Party> parties; List<FormedParty> formed; }
    private final Supabase db;
    private final Clan clan;
    private final ThreadLocal<Session> actor = new ThreadLocal<>();
    private volatile Snapshot snapshot = new Snapshot(Collections.emptyList(), Collections.emptyList());
    @Inject public PartyApi(Supabase db, Clan clan) { this.db = db; this.clan = clan; }

    public boolean inSession(Session session, java.util.function.BooleanSupplier action)
    {
        actor.set(session);
        try { return clan.current(session) && action.getAsBoolean(); }
        finally { actor.remove(); }
    }

    public Snapshot fetch()
    {
        ApiResult response = db.rpcResult("fb_board", new JsonObject());
        if (!response.successful() || response.getBody() == null || !response.getBody().isJsonObject()) return null;
        JsonObject body = response.getBody().getAsJsonObject();
        if (Supabase.intOr(body, "protocol", 0) != 3) return null;
        List<Party> parties = new ArrayList<>();
        List<FormedParty> formed = new ArrayList<>();
        try
        {
            for (JsonElement el : body.getAsJsonArray("parties"))
            {
                Party p = Party.fromRow(el.getAsJsonObject());
                if (p == null) return null;
                parties.add(p);
            }
            for (JsonElement el : body.getAsJsonArray("formed"))
            {
                FormedParty f = FormedParty.fromRow(el.getAsJsonObject());
                if (f == null) return null;
                formed.add(f);
            }
        }
        catch (RuntimeException e) { return null; }
        return new Snapshot(Collections.unmodifiableList(parties), Collections.unmodifiableList(formed));
    }

    public void publish(Snapshot value) { snapshot = value; }
    private Party find(String id)
    {
        for (Party p : snapshot.parties) if (p.getId().equals(id)) return p;
        return null;
    }
    private Party hosted(String rsn)
    {
        for (Party p : snapshot.parties) if (p.isHostedBy(rsn)) return p;
        return null;
    }
    private boolean command(String action, JsonObject data, Long expected)
    {
        Session session = actor.get() == null ? clan.snapshot() : actor.get();
        if (!clan.current(session)) return false;
        JsonObject args = new JsonObject();
        args.addProperty("p_action", action);
        args.addProperty("p_actor", session.getRsn());
        args.add("p_data", data);
        args.addProperty("p_operation", UUID.randomUUID().toString());
        if (expected != null) args.addProperty("p_expected", expected);
        for (int attempt = 0; attempt < 2 && clan.current(session); attempt++)
        {
            ApiResult result = db.rpcResult("fb_lfg", args);
            if (result.successful()) return true;
            if (!result.retryable()) return false;
        }
        return false;
    }
    private JsonObject data(String id) { JsonObject d = new JsonObject(); d.addProperty("id", id); return d; }
    private boolean command(String action, JsonObject d)
    {
        Party p = find(Supabase.str(d, "id"));
        return command(action, d, p == null ? null : p.getVersion());
    }
    public boolean save(Party party)
    {
        JsonObject d = party.toJson();
        if (party.getId() != null) d.addProperty("id", party.getId());
        return command(party.getId() == null ? "create" : "edit", d,
            party.getId() == null ? null : party.getVersion());
    }
    public boolean heartbeat(String rsn)
    {
        Party p = hosted(rsn);
        return p != null && command("heartbeat", data(p.getId()), null);
    }
    public boolean disband(String id)
    {
        return command("disband", data(id));
    }
    public boolean apply(String id, String rsn, Role role, boolean learner, Integer kc, Party.KcSource source)
    {
        JsonObject d = data(id);
        Supabase.put(d, "role", role == null ? null : role.key());
        d.addProperty("learner", learner);
        Supabase.put(d, "kc", kc);
        Supabase.put(d, "kc_source", source == null ? null : source.name());
        return command("apply", d);
    }
    public boolean withdraw(String id, String rsn)
    {
        Party p = find(id);
        Session s = actor.get() == null ? clan.snapshot() : actor.get();
        JsonObject d = data(id); d.addProperty("rsn", rsn);
        return command(p != null && p.isHostedBy(s.getRsn()) ? "kick" : "leave", d);
    }
    public boolean setStatus(String id, String rsn, Party.Status status)
    {
        JsonObject d = data(id); d.addProperty("rsn", rsn);
        return command(status == Party.Status.ACCEPTED ? "accept" : "decline", d);
    }
    public AddResult addMember(String id, String rsn, Role role)
    {
        JsonObject d = data(id); d.addProperty("rsn", rsn);
        Supabase.put(d, "role", role == null ? null : role.key());
        return command("add", d) ? AddResult.OK : AddResult.REJECTED;
    }
    public boolean deleteFormed(String id) { return command("remove_formed", data(id), null); }
}

package com.github.orgonag.fbclan.lfg;

import lombok.Getter;

/** How a party splits drops. Stored by enum name; unknown reads as UNSPECIFIED. */
@Getter
public enum LootRule
{
    UNSPECIFIED("Loot: any"), FFA("FFA"), SPLIT("Split");

    private final String displayName;

    LootRule(String displayName)
    {
        this.displayName = displayName;
    }

    public static LootRule fromKey(String key)
    {
        for (LootRule rule : values())
        {
            if (key != null && rule.name().equalsIgnoreCase(key.trim()))
            {
                return rule;
            }
        }
        return UNSPECIFIED;
    }

    @Override
    public String toString()
    {
        return displayName;
    }
}

package com.github.orgonag.fbclan.lfg;

import com.github.orgonag.fbclan.FinalBossConfig;
import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.core.Names;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.util.Text;

/**
 * The read-only "!lfg" chat command: the local player's own "!lfg" (or
 * "!lfg parties") prints the open parties to their chatbox; anything
 * else prints usage. Nothing is hosted, applied to, or changed from
 * chat, the typed message still posts normally, and other players'
 * commands are ignored.
 */
@Singleton
public class LfgCommand
{
    private static final String USAGE = "Usage: !lfg (lists open parties). Use the Final Boss panel to host or apply.";
    private static final Set<ChatMessageType> LOCAL_AUTHOR = EnumSet.of(
        ChatMessageType.PUBLICCHAT, ChatMessageType.MODCHAT, ChatMessageType.FRIENDSCHAT,
        ChatMessageType.CLAN_CHAT, ChatMessageType.CLAN_GUEST_CHAT, ChatMessageType.PRIVATECHATOUT);

    private final Client client;
    private final ClientThread clientThread;
    private final FinalBossConfig config;
    private final Clan clan;
    private final PartyApi api;
    private final ScheduledExecutorService executor;

    @Inject
    public LfgCommand(Client client, ClientThread clientThread, FinalBossConfig config, Clan clan, PartyApi api,
                      ScheduledExecutorService executor)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.config = config;
        this.clan = clan;
        this.api = api;
        this.executor = executor;
    }

    // Client thread.
    public void onChatMessage(ChatMessage event)
    {
        if (!config.enableLfg() || !clan.canUpload() || !LOCAL_AUTHOR.contains(event.getType()))
        {
            return;
        }
        // PRIVATECHATOUT's name is the recipient; the author is us by definition.
        if (event.getType() != ChatMessageType.PRIVATECHATOUT
            && (event.getName() == null || !Names.same(Text.removeTags(event.getName()), clan.rsn())))
        {
            return;
        }
        String text = Text.removeTags(event.getMessage()).trim();
        if (!text.toLowerCase(Locale.ROOT).startsWith("!lfg"))
        {
            return;
        }
        String rest = text.substring(4);
        if (!rest.isEmpty() && !Character.isWhitespace(rest.charAt(0)))
        {
            return; // "!lfgsomething" is a different command
        }
        String keyword = rest.trim().split("\\s+", 2)[0].toLowerCase(Locale.ROOT);
        if (keyword.isEmpty() || keyword.equals("parties") || keyword.equals("party"))
        {
            com.github.orgonag.fbclan.core.Session session = clan.snapshot();
            executor.submit(() -> {
                if (!clan.current(session) || !config.enableLfg()) return;
                PartyApi.Snapshot snapshot = api.fetch();
                List<Party> parties = snapshot == null ? null : snapshot.getParties();
                String reply = parties == null ? "Couldn't reach the party board — try again." : summarize(parties);
                clientThread.invokeLater(() -> {
                    if (clan.current(session) && config.enableLfg() && client.getGameState() == GameState.LOGGED_IN)
                    {
                        print(reply);
                    }
                });
            });
        }
        else
        {
            print(USAGE);
        }
    }

    // "Parties: HMT - Host 3/5 W420 - needs Melee, North freeze | ..."
    static String summarize(List<Party> parties)
    {
        if (parties.isEmpty())
        {
            return "No parties are being hosted right now.";
        }
        StringBuilder sb = new StringBuilder("Parties: ");
        boolean first = true;
        for (Party p : parties)
        {
            if (sb.length() > 600) { sb.append(" | More in the panel."); break; }
            sb.append(first ? "" : " | ").append(p.title()).append(" - ").append(p.getHostRsn())
                .append(' ').append(p.memberCount()).append('/').append(p.getCapacity());
            first = false;
            if (p.getWorld() != null)
            {
                sb.append(" W").append(p.getWorld());
            }
            if (p.isFull())
            {
                sb.append(" (full)");
            }
            else
            {
                String needs = Role.summarize(p.openRoles());
                if (!needs.isEmpty())
                {
                    sb.append(" - needs ").append(needs);
                }
            }
        }
        return sb.toString();
    }

    private void print(String message)
    {
        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
    }
}

package com.github.orgonag.fbclan.lfg;

import com.github.orgonag.fbclan.FinalBossConfig;
import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.core.Session;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;

/**
 * The live state behind the parties tab. Owns the 30-second poll, the
 * cached snapshot, the host heartbeat, forming a full party, and the
 * diff between consecutive polls that becomes chat/desktop
 * notifications. The tab only renders what this holds.
 */
@Slf4j
@Singleton
public class PartyBoard
{
    public static final int HEARTBEAT_MINUTES = 5;

    public interface Listener
    {
        // Executor thread; the tab hops to the EDT.
        void onChanged();
    }

    private final Client client;
    private final ClientThread clientThread;
    private final FinalBossConfig config;
    private final Clan clan;
    private final PartyApi api;
    private final Notifier notifier;
    private final ScheduledExecutorService executor;

    private volatile List<Party> parties = Collections.emptyList();
    private volatile List<FormedParty> formed = Collections.emptyList();
    private volatile Set<String> online = Collections.emptySet();
    private volatile int world;
    private volatile Listener listener = () -> {};
    private ScheduledFuture<?> poll;
    private volatile long lastHeartbeat;
    private volatile boolean enabled;
    private volatile long epoch;
    private volatile String refreshError;
    public String refreshError() { return refreshError; }
    private final AtomicBoolean refreshing = new AtomicBoolean();
    private final AtomicBoolean writing = new AtomicBoolean();
    public boolean isBusy() { return writing.get(); }

    // Diff state; guarded by `this`.
    private Map<String, Party> previous = Collections.emptyMap();
    private Set<String> previousFormed = Collections.emptySet();
    private boolean primed;
    private final Set<String> selfLeft = new HashSet<>();

    @Inject
    public PartyBoard(Client client, ClientThread clientThread, FinalBossConfig config, Clan clan, PartyApi api,
                      Notifier notifier, ScheduledExecutorService executor)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.config = config;
        this.clan = clan;
        this.api = api;
        this.notifier = notifier;
        this.executor = executor;
    }

    public void setListener(Listener listener)
    {
        this.listener = listener;
    }

    public List<Party> parties()
    {
        return parties;
    }

    public List<FormedParty> formed()
    {
        return formed;
    }

    // Normalized names of clan members currently in the clan channel.
    public Set<String> online()
    {
        return online;
    }

    public int world()
    {
        return world;
    }

    public Party mine()
    {
        String rsn = clan.rsn();
        for (Party p : parties)
        {
            if (p.isHostedBy(rsn))
            {
                return p;
            }
        }
        return null;
    }

    // ------------------------------------------------------------ lifecycle

    public synchronized void start()
    {
        if (!config.enableLfg() || poll != null)
        {
            return;
        }
        enabled = true;
        poll = executor.scheduleAtFixedRate(() -> {
            try
            {
                refresh();
            }
            catch (Exception e)
            {
                log.warn("LFG poll error", e);
            }
        }, 0, 30, TimeUnit.SECONDS);
    }

    public synchronized void stop()
    {
        enabled = false;
        epoch++;
        lastHeartbeat = 0;
        online = Collections.emptySet();
        world = 0;
        api.publish(new PartyApi.Snapshot(Collections.emptyList(), Collections.emptyList()));
        if (poll != null)
        {
            poll.cancel(true);
            poll = null;
        }
        synchronized (this)
        {
            previous = Collections.emptyMap();
            previousFormed = Collections.emptySet();
            primed = false;
            selfLeft.clear();
        }
        parties = Collections.emptyList();
        formed = Collections.emptyList();
    }

    // Called by the tab before the local player withdraws/disbands, so the
    // next diff doesn't announce their own action back at them.
    public synchronized void expectSelfLeave(String partyId)
    {
        if (partyId != null)
        {
            selfLeft.add(partyId);
        }
    }

    // Executor. Fetch; form the hosted party if it filled; heartbeat; diff.
    // A failed fetch leaves the snapshot alone: an outage must never read
    // as "every party was disbanded".
    public void refresh()
    {
        Session session = clan.snapshot();
        long capturedEpoch = epoch;
        if (!enabled || !config.enableLfg() || !clan.current(session) || !refreshing.compareAndSet(false, true)) return;
        try
        {
            clientThread.invokeLater(() -> { if (enabled && capturedEpoch == epoch && clan.current(session)) readClient(); });
            PartyApi.Snapshot fetched = api.fetch();
            if (fetched == null)
            {
                if (enabled && capturedEpoch == epoch && clan.current(session))
                { refreshError = "Board unavailable. Showing the last loaded parties."; listener.onChanged(); }
                return;
            }
            synchronized (this)
            {
                if (!enabled || capturedEpoch != epoch || !clan.current(session)) return;
                refreshError = null;
                api.publish(fetched);
                parties = fetched.getParties();
                formed = fetched.getFormed();
                notify(parties, formed, session.getRsn());
            }
            if (enabled && capturedEpoch == epoch && config.enableLfg() && mine() != null && System.currentTimeMillis() - lastHeartbeat >= HEARTBEAT_MINUTES * 60_000L
                && api.inSession(session, () -> api.heartbeat(session.getRsn()))) lastHeartbeat = System.currentTimeMillis();
            if (enabled && capturedEpoch == epoch && clan.current(session)) listener.onChanged();
        }
        finally { refreshing.set(false); }
    }

    public void run(java.util.function.BooleanSupplier action, String failure, java.util.function.Consumer<String> onError)
    {
        Session session = clan.snapshot();
        long capturedEpoch = epoch;
        if (!enabled || !config.enableLfg() || !clan.current(session) || !writing.compareAndSet(false, true))
        {
            onError.accept("Wait for the current action, or reconnect and refresh.");
            return;
        }
        listener.onChanged();
        executor.submit(() -> {
            boolean ok = false;
            try { if (enabled && capturedEpoch == epoch && config.enableLfg()) ok = api.inSession(session, action); }
            catch (RuntimeException e) { log.warn("LFG action failed", e); }
            finally { writing.set(false); }
            if (enabled && capturedEpoch == epoch && clan.current(session))
            {
                onError.accept(ok ? null : failure);
                refresh();
                listener.onChanged();
            }
        });
    }

    public void markHeartbeat()
    {
        lastHeartbeat = System.currentTimeMillis();
    }

    private void readClient()
    {
        Set<String> names = new HashSet<>();
        ClanChannel cc = client.getClanChannel();
        if (cc != null)
        {
            for (ClanChannelMember m : cc.getMembers())
            {
                if (m.getName() != null)
                {
                    names.add(com.github.orgonag.fbclan.core.Names.normalize(m.getName()));
                }
            }
        }
        boolean changed = !online.equals(names) || world != client.getWorld();
        online = Collections.unmodifiableSet(names);
        world = client.getWorld();
        if (changed) listener.onChanged();
    }

    // ------------------------------------------------------------ notifications

    private void notify(List<Party> now, List<FormedParty> formedNow, String rsn)
    {
        if (rsn == null)
        {
            return;
        }
        Map<String, Party> nowById = new HashMap<>();
        for (Party p : now)
        {
            nowById.put(p.getId(), p);
        }
        Set<String> formedIds = new HashSet<>();
        Set<String> formedFrom = new HashSet<>();
        for (FormedParty f : formedNow)
        {
            formedIds.add(f.getId());
            if (f.getPartyId() != null)
            {
                formedFrom.add(f.getPartyId());
            }
        }
        List<String> messages = new ArrayList<>();
        synchronized (this)
        {
            if (primed)
            {
                diff(previous, nowById, rsn, formedFrom, messages);
                for (FormedParty f : formedNow)
                {
                    if (!previousFormed.contains(f.getId()) && f.includes(rsn))
                    {
                        messages.add((f.isHostedBy(rsn) ? "Your" : f.getHostRsn() + "'s") + " " + f.title()
                            + " party has formed" + (f.getWorld() != null ? " (World " + f.getWorld() + ")" : "")
                            + ": " + f.roster() + ".");
                    }
                }
            }
            previous = nowById;
            previousFormed = formedIds;
            primed = true;
        }
        for (String m : messages)
        {
            deliver(m);
        }
    }

    private void diff(Map<String, Party> prev, Map<String, Party> now, String rsn, Set<String> formedFrom, List<String> out)
    {
        for (Party p : now.values())
        {
            Party before = prev.get(p.getId());
            if (p.isHostedBy(rsn))
            {
                for (Party.Applicant a : p.pending())
                {
                    if (before == null || before.applicantFor(a.getRsn()) == null)
                    {
                        out.add(a.getRsn() + " applied to your " + p.title() + " party"
                            + (a.getRole() == null ? "" : " as " + a.getRole().getDisplayName())
                            + (a.isLearner() ? " (learner)" : "") + ".");
                    }
                }
                continue;
            }
            Party.Applicant mine = p.applicantFor(rsn);
            Party.Applicant mineBefore = before == null ? null : before.applicantFor(rsn);
            if (mine != null && mineBefore != null && mine.getStatus() != mineBefore.getStatus())
            {
                if (mine.isAccepted())
                {
                    out.add("You've been accepted to " + p.getHostRsn() + "'s " + p.title() + " party"
                        + (p.getWorld() != null ? " (World " + p.getWorld() + ")" : "") + ".");
                }
                else if (mine.getStatus() == Party.Status.DECLINED)
                {
                    out.add(p.getHostRsn() + " declined your " + p.title() + " application.");
                }
            }
            else if (mine == null && mineBefore != null && !selfLeft.remove(p.getId())
                && mineBefore.getStatus() != Party.Status.DECLINED)
            {
                out.add("You were removed from " + p.getHostRsn() + "'s " + p.title() + " party.");
            }
        }
        // Parties that vanished while the player was in them (a formed
        // party is announced from the formed list instead).
        for (Party before : prev.values())
        {
            if (now.containsKey(before.getId()) || before.isHostedBy(rsn) || formedFrom.contains(before.getId()))
            {
                continue;
            }
            Party.Applicant mineBefore = before.applicantFor(rsn);
            if (mineBefore != null && mineBefore.getStatus() != Party.Status.DECLINED && !selfLeft.remove(before.getId()))
            {
                out.add(before.getHostRsn() + "'s " + before.title() + " party was disbanded.");
            }
        }
        selfLeft.clear();
    }

    private void deliver(String message)
    {
        Session session = clan.snapshot();
        long capturedEpoch = epoch;
        if (config.lfgPartyNotifications())
        {
            clientThread.invokeLater(() -> {
                if (enabled && capturedEpoch == epoch && clan.current(session) && client.getGameState() == GameState.LOGGED_IN)
                {
                    client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "[LFG] " + message, null);
                }
            });
        }
        if (config.lfgDesktopNotifications())
        {
            notifier.notify("Final Boss LFG: " + message);
        }
    }
}

package com.github.orgonag.fbclan.pbs;

import com.github.orgonag.fbclan.FinalBossConfig;
import com.github.orgonag.fbclan.core.Clan;
import com.github.orgonag.fbclan.core.Session;
import com.github.orgonag.fbclan.core.Supabase;
import com.github.orgonag.fbclan.pbs.PbParser.Duration;
import com.github.orgonag.fbclan.pbs.PbParser.Submission;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;

/**
 * Upload side of the PB leaderboard. Pairs the two chat lines a kill
 * produces (kill count carries the boss, duration carries the time,
 * either order, same tick) exactly like core ChatCommands, and once per
 * session seeds the PBs RuneLite already stores locally. Everything goes
 * through the improve-only submit_pbs function, so a worse time is a
 * silent no-op server-side.
 */
@Slf4j
@Singleton
public class PersonalBests
{
    private static final int MAX_BATCH = 250; // submit_pbs rejects > 300

    private final Client client;
    private final FinalBossConfig config;
    private final Clan clan;
    private final Supabase db;
    private final ConfigManager configManager;
    private final ScheduledExecutorService executor;

    private final PbCorrelator correlator = new PbCorrelator();
    private volatile long seededGeneration = -1;
    private final java.util.concurrent.atomic.AtomicBoolean seeding = new java.util.concurrent.atomic.AtomicBoolean();

    @Inject
    public PersonalBests(Client client, FinalBossConfig config, Clan clan, Supabase db,
                         ConfigManager configManager, ScheduledExecutorService executor)
    {
        this.client = client;
        this.config = config;
        this.clan = clan;
        this.db = db;
        this.configManager = configManager;
        this.executor = executor;
    }

    public void resetSession()
    {
        seededGeneration = -1;
        correlator.reset();
    }

    // Client thread (chat dispatch).
    public void onChatMessage(ChatMessage event)
    {
        ChatMessageType type = event.getType();
        if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM
            && type != ChatMessageType.FRIENDSCHATNOTIFICATION)
        {
            return;
        }
        Session session = clan.snapshot();
        if (!clan.canUpload() || !config.enablePbUpload() || !clan.onStandardWorld())
        {
            return;
        }
        List<Submission> subs = correlator.accept(event.getMessage(), client.getTickCount(), this::raidTeam);
        if (!subs.isEmpty())
        {
            executor.submit(() -> { if (!submit(session, subs) && clan.current(session)) seededGeneration = -1; });
        }
    }

    // Once per session, after verification: push RuneLite's stored PBs so
    // the board is complete from day one.
    public void maybeSeed()
    {
        Session session = clan.snapshot();
        if (!clan.current(session) || seededGeneration == session.getGeneration() || !config.enablePbUpload()
            || !clan.onStandardWorld() || !seeding.compareAndSet(false, true)) return;
        // Capture all profile-dependent reads on the client thread, before queuing I/O.
        List<Submission> seeds = new ArrayList<>();
        try
        {
            if (!session.getProfile().equals(configManager.getRSProfileKey())) return;
            for (String key : configManager.getRSProfileConfigurationKeys("personalbest", session.getProfile(), ""))
            {
                try
                {
                    Double seconds = configManager.getRSProfileConfiguration("personalbest", key, double.class);
                    if (key != null && !key.isEmpty() && seconds != null && Double.isFinite(seconds) && seconds > 0 && seconds < 86400)
                        seeds.add(new Submission(key, seconds, "seed"));
                }
                catch (RuntimeException e) { log.debug("Ignoring invalid stored PB"); }
            }
        }
        finally { seeding.set(false); }
        if (!seeding.compareAndSet(false, true)) return;
        executor.submit(() -> {
            try { if (submit(session, seeds) && clan.current(session)) seededGeneration = session.getGeneration(); }
            finally { seeding.set(false); }
        });
    }

    private String raidTeam(String boss)
    {
        if (boss.contains("theatre of blood")) return teamLabel(teamSize(VarbitID.TOB_CLIENT_P0, VarbitID.TOB_CLIENT_P1,
            VarbitID.TOB_CLIENT_P2, VarbitID.TOB_CLIENT_P3, VarbitID.TOB_CLIENT_P4));
        if (boss.contains("tombs of amascut")) return teamLabel(teamSize(VarbitID.TOA_CLIENT_P0, VarbitID.TOA_CLIENT_P1,
            VarbitID.TOA_CLIENT_P2, VarbitID.TOA_CLIENT_P3, VarbitID.TOA_CLIENT_P4, VarbitID.TOA_CLIENT_P5,
            VarbitID.TOA_CLIENT_P6, VarbitID.TOA_CLIENT_P7));
        return null;
    }

    private int teamSize(int... varbits)
    {
        int n = 0;
        for (int v : varbits)
        {
            n += Math.min(client.getVarbitValue(v), 1);
        }
        return n;
    }

    private static String teamLabel(int size)
    {
        return size == 0 ? null : size == 1 ? "Solo" : size + " players";
    }

    // ------------------------------------------------------------ submit

    private boolean submit(Session session, List<Submission> subs)
    {
        for (int start = 0; start < subs.size(); start += MAX_BATCH)
        {
            if (!clan.current(session) || !config.enablePbUpload()) return false;
            List<Submission> chunk = subs.subList(start, Math.min(start + MAX_BATCH, subs.size()));
            JsonArray entries = new JsonArray();
            for (Submission s : chunk)
            {
                JsonObject e = new JsonObject();
                e.addProperty("boss_key", s.getBossKey());
                e.addProperty("seconds", s.getSeconds());
                e.addProperty("source", s.getSource());
                entries.add(e);
            }
            JsonObject payload = new JsonObject();
            payload.addProperty("p_rsn", session.getRsn());
            payload.add("p_entries", entries);
            if (!db.rpc("fb_submit_pbs", payload)) return false;
        }
        return true;
    }
}

package com.github.orgonag.fbclan.pbs;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/** Client-thread confined; both halves expire together and a match consumes both. */
public final class PbCorrelator
{
    private int tick = -1;
    private String boss;
    private PbParser.Duration duration;

    public void reset() { tick = -1; boss = null; duration = null; }

    public List<PbParser.Submission> accept(String message, int now, java.util.function.Function<String, String> team)
    {
        if (now != tick) { reset(); tick = now; }
        List<PbParser.Submission> standalone = PbParser.sepulchre(message);
        if (!standalone.isEmpty()) { reset(); return standalone; }
        java.util.Optional<String> kc = PbParser.killCount(message);
        if (kc.isPresent()) boss = kc.get();
        else
        {
            java.util.Optional<PbParser.Duration> parsed = PbParser.duration(message);
            if (parsed.isPresent()) duration = parsed.get();
        }
        if (boss == null || duration == null) return Collections.emptyList();
        List<PbParser.Submission> out = new ArrayList<>();
        double seconds = duration.getSeconds();
        if (Double.isFinite(seconds) && seconds > 0 && seconds < 86400)
        {
            String source = duration.isNewPb() ? "live" : "seed";
            out.add(new PbParser.Submission(boss, seconds, source));
            String size = team.apply(boss);
            if (size == null) size = duration.getTeamSize();
            if (size != null) out.add(new PbParser.Submission(boss + " " + size.toLowerCase(Locale.ROOT), seconds, source));
        }
        reset();
        return out;
    }
}

package com.github.orgonag.fbclan.pbs;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;

/**
 * Parsing and formatting for OSRS kill-count / personal-best chat lines.
 * Patterns are copied verbatim from RuneLite core's ChatCommandsPlugin
 * and match the RAW message with colour tags intact. Boss keys are
 * canonicalized exactly like core stores them (renames, colons stripped,
 * lowercased) so seeded and live data share keys.
 */
public final class PbParser
{
    private static final Pattern KILLCOUNT = Pattern.compile("Your (?<pre>completion count for |subdued |completed )?(?:<col=[0-9a-f]{6}>)?(?<boss>.+?)(?:</col>)? (?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?(?:count )?)is: ?<col=[0-9a-f]{6}>(?<kc>[0-9,]+)</col>");
    private static final String TEAM = "(?<teamsize>\\d+(?:\\+|-\\d+)? players?|Solo)";
    private static final Pattern RAID_NEW_PB = Pattern.compile("<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>" + TEAM + "</col> Duration:</col> <col=ff0000>(?<pb>[0-9:]+(?:\\.[0-9]+)?)</col> \\(new personal best\\)</col>");
    private static final Pattern RAID_DURATION = Pattern.compile("<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>" + TEAM + "</col> Duration:</col> <col=ff0000>[0-9:.]+</col> Personal best: </col><col=ff0000>(?<pb>[0-9:]+(?:\\.[0-9]+)?)</col>");
    private static final Pattern KILL_DURATION = Pattern.compile("(?i)(?:(?:Fight |Lap |Challenge |Corrupted challenge )?duration:|Subdued in|(?<!total )completion time:) <col=[0-9a-f]{6}>[0-9:.]+</col>\\. Personal best: (?:<col=ff0000>)?(?<pb>[0-9:]+(?:\\.[0-9]+)?)");
    private static final Pattern NEW_PB = Pattern.compile("(?i)(?:(?:Fight |Lap |Challenge |Corrupted challenge )?duration:|Subdued in|(?<!total )completion time:) <col=[0-9a-f]{6}>(?<pb>[0-9:]+(?:\\.[0-9]+)?)</col> \\(new personal best\\)");
    private static final Pattern SEPULCHRE = Pattern.compile("Floor (?<floor>\\d) time: <col=ff0000>(?<floortime>[0-9:]+(?:\\.[0-9]+)?)</col>(?: \\(new personal best\\)|. Personal best: (?<floorpb>[0-9:]+(?:\\.[0-9]+)?))"
        + "(?:<br>Overall time: <col=ff0000>(?<otime>[0-9:]+(?:\\.[0-9]+)?)</col>(?: \\(new personal best\\)|. Personal best: (?<opb>[0-9:]+(?:\\.[0-9]+)?)))?");
    private static final Pattern TEAM_SUFFIX = Pattern.compile(" (solo|\\d+(?:\\+|-\\d+)? players?)$");
    private static final String[][] RAID_ABBREVIATIONS = {
        {"chambers of xeric challenge mode", "CM"},
        {"chambers of xeric", "COX"},
        {"theatre of blood hard mode", "HMT"},
        {"theatre of blood", "TOB"},
        {"tombs of amascut expert mode", "TOA Expert"},
        {"tombs of amascut", "TOA"},
    };

    private static String colors(String message)
    {
        // RuneLite preserves unresolved Jagex color tokens in newer game messages.
        return message.replaceAll("@[A-Za-z0-9_]+@", "<col=ff0000>");
    }

    private PbParser()
    {
    }

    /** One PB headed for the database. source: "live" = fresh record, "seed" = backfill. */
    @Value
    public static class Submission
    {
        String bossKey;
        double seconds;
        String source;
    }

    /** A duration line: the time, whether it's a fresh record, CoX team size if any. */
    @Value
    public static class Duration
    {
        double seconds;
        boolean newPb;
        String teamSize;
    }

    // KC line -> canonical boss key. Personal-count rows ("Your Glory
    // is: ...") have neither pre nor post and are not boss KCs.
    public static Optional<String> killCount(String message)
    {
        Matcher m = KILLCOUNT.matcher(colors(message));
        if (!m.find())
        {
            return Optional.empty();
        }
        String pre = m.group("pre");
        String post = m.group("post");
        if ((pre == null || pre.isEmpty()) && (post == null || post.isEmpty()))
        {
            return Optional.empty();
        }
        return Optional.of(canonicalKey(m.group("boss")));
    }

    public static Optional<Duration> duration(String message)
    {
        Matcher m = NEW_PB.matcher(colors(message));
        if (m.find())
        {
            return Optional.of(new Duration(seconds(m.group("pb")), true, null));
        }
        m = KILL_DURATION.matcher(colors(message));
        if (m.find())
        {
            return Optional.of(new Duration(seconds(m.group("pb")), false, null));
        }
        m = RAID_NEW_PB.matcher(colors(message));
        if (m.find())
        {
            return Optional.of(new Duration(seconds(m.group("pb")), true, m.group("teamsize")));
        }
        m = RAID_DURATION.matcher(colors(message));
        if (m.find())
        {
            return Optional.of(new Duration(seconds(m.group("pb")), false, m.group("teamsize")));
        }
        return Optional.empty();
    }

    // Hallowed Sepulchre carries its identity in the line itself: floor
    // time always, overall time optionally. A "(new personal best)"
    // segment is live; a restated "Personal best: X" is backfill.
    public static List<Submission> sepulchre(String message)
    {
        List<Submission> out = new ArrayList<>();
        Matcher m = SEPULCHRE.matcher(colors(message));
        if (!m.find())
        {
            return out;
        }
        String floor = "hallowed sepulchre floor " + m.group("floor");
        String floorPb = m.group("floorpb");
        out.add(floorPb != null
            ? new Submission(floor, seconds(floorPb), "seed")
            : new Submission(floor, seconds(m.group("floortime")), "live"));
        String oTime = m.group("otime");
        if (oTime != null)
        {
            String oPb = m.group("opb");
            out.add(oPb != null
                ? new Submission("hallowed sepulchre", seconds(oPb), "seed")
                : new Submission("hallowed sepulchre", seconds(oTime), "live"));
        }
        out.removeIf(sub -> !Double.isFinite(sub.getSeconds()));
        return out;
    }

    public static String canonicalKey(String boss)
    {
        String renamed = "Barrows chest".equals(boss) ? "Barrows Chests" : boss;
        return renamed.replace(":", "").toLowerCase(Locale.ROOT);
    }

    // Verbatim port of core's timeStringToSeconds.
    public static double seconds(String time)
    {
        try
        {
            if (!time.matches("[0-9]+(?::[0-9]{1,2}){0,2}(?:\\.[0-9]{1,2})?")) return Double.NaN;
            String[] parts = time.split(":");
            double value = 0;
            for (int i = 0; i < parts.length; i++)
            {
                double part = Double.parseDouble(parts[i]);
                if (i > 0 && part >= 60) return Double.NaN;
                value = value * 60 + part;
            }
            return value > 0 && value < 86400 ? value : Double.NaN;
        }
        catch (RuntimeException e) { return Double.NaN; }
    }

    // Port of core's secondsToTimeString: whole seconds without ".00".
    public static String formatSeconds(double seconds)
    {
        int hours = (int) (Math.floor(seconds) / 3600);
        int minutes = (int) (Math.floor(seconds / 60) % 60);
        seconds = seconds % 60;
        String prefix = hours > 0 ? String.format(Locale.ROOT, "%d:%02d:", hours, minutes) : String.format(Locale.ROOT, "%d:", minutes);
        return prefix + (Math.floor(seconds) == seconds
            ? String.format(Locale.ROOT, "%02d", (int) seconds)
            : String.format(Locale.ROOT, "%05.2f", seconds));
    }

    // "theatre of blood 4 players" -> "TOB (4 players)". Cosmetic only.
    public static String displayName(String bossKey)
    {
        String base = bossKey;
        String suffix = null;
        Matcher m = TEAM_SUFFIX.matcher(bossKey);
        if (m.find())
        {
            base = bossKey.substring(0, m.start());
            suffix = m.group(1).equals("solo") ? "Solo" : m.group(1);
        }
        StringBuilder sb = new StringBuilder();
        for (String[] abbr : RAID_ABBREVIATIONS)
        {
            if (base.equals(abbr[0]))
            {
                sb.append(abbr[1]);
                base = "";
                break;
            }
            if (base.startsWith(abbr[0] + " "))
            {
                sb.append(abbr[1]);
                base = base.substring(abbr[0].length() + 1);
                break;
            }
        }
        for (String word : base.split(" "))
        {
            if (word.isEmpty())
            {
                continue;
            }
            if (sb.length() > 0)
            {
                sb.append(' ');
            }
            sb.append(Character.toUpperCase(word.charAt(0))).append(word.substring(1).toLowerCase(Locale.ROOT));
        }
        if (suffix != null)
        {
            sb.append(" (").append(suffix).append(')');
        }
        return sb.toString();
    }
}

package com.github.orgonag.fbclan.pbs;

import com.github.orgonag.fbclan.core.Supabase;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;

/**
 * Read side of the PB leaderboard: the pb_leaderboard view (top 3 per
 * boss, server-ranked) and recent_clan_bests (live-sourced current #1s,
 * newest first). Each fetch fails soft independently, keeping last data.
 */
@Singleton
public class Leaderboards
{
    @Value
    public static class Entry
    {
        String rsn;
        String bossKey;
        double seconds;
        String achievedAt; // ISO timestamp, may be blank
        int rank;          // 1..3 on the board, 1 in the feed
    }

    private final Supabase db;
    private volatile List<Entry> board = Collections.emptyList();
    private volatile List<Entry> recent = Collections.emptyList();

    @Inject
    public Leaderboards(Supabase db)
    {
        this.db = db;
    }

    public List<Entry> board()
    {
        return board;
    }

    public List<Entry> recent()
    {
        return recent;
    }

    // Executor. A failed fetch keeps the previous board.
    public boolean refresh()
    {
        boolean complete = true;
        JsonArray rows = db.getOrNull("pb_leaderboard", "select=rsn,boss_key,seconds,achieved_at,rank&order=boss_key.asc,rank.asc,rsn.asc");
        if (rows != null)
        {
            board = parse(rows);
        }
        else complete = false;
        rows = db.getOrNull("recent_clan_bests", "select=rsn,boss_key,seconds,achieved_at&order=achieved_at.desc");
        if (rows != null)
        {
            recent = parse(rows);
        }
        else complete = false;
        return complete;
    }

    private static List<Entry> parse(JsonArray rows)
    {
        List<Entry> out = new ArrayList<>();
        for (JsonElement el : rows)
        {
            if (!el.isJsonObject()) continue;
            JsonObject row = el.getAsJsonObject();
            String rsn = Supabase.str(row, "rsn");
            String boss = Supabase.str(row, "boss_key");
            if (rsn.isEmpty() || boss.isEmpty() || !Supabase.has(row, "seconds"))
            {
                continue;
            }
            double seconds = Supabase.doubleOr(row, "seconds", -1);
            if (seconds <= 0 || seconds >= 86400) continue;
            out.add(new Entry(rsn, boss, seconds,
                Supabase.str(row, "achieved_at"), Supabase.intOr(row, "rank", 1)));
        }
        return Collections.unmodifiableList(out);
    }
}
